79	void OBCameraNode::setupDevices() {
80	  auto sensor_list = device_->getSensorList();
81	  for (size_t i = 0; i < sensor_list->count(); i++) {
82	    auto sensor = sensor_list->getSensor(i);
83	    auto profiles = sensor->getStreamProfileList();
84	    for (size_t j = 0; j < profiles->count(); j++) {
85	      auto profile = profiles->getProfile(j);
86	      stream_index_pair sip{profile->type(), 0};
87	      if (sensors_.find(sip) != sensors_.end()) {
88	        continue;
89	      }
90	      sensors_[sip] = sensor;
91	    }
92	  }
93	
94	  for (const auto& [stream_index, enable] : enable_stream_) {
95	    if (enable && sensors_.find(stream_index) == sensors_.end()) {
96	      RCLCPP_INFO_STREAM(logger_,
97	                         magic_enum::enum_name(stream_index.first)
98	                             << "sensor isn't supported by current device! -- Skipping...");
99	      enable_stream_[stream_index] = false;
100	    }
101	  }
102	  auto info = device_->getDeviceInfo();
103	  if (enable_hardware_d2d_ && info->pid() == GEMINI2_PID) {
104	    device_->setBoolProperty(OB_PROP_DISPARITY_TO_DEPTH_BOOL, true);
105	  }
106	  try {
107	    if (!depth_work_mode_.empty()) {
108	      device_->switchDepthWorkMode(depth_work_mode_.c_str());
109	    }
110	    if (sync_mode_ != OB_SYNC_MODE_CLOSE) {
111	      OBDeviceSyncConfig sync_config;
112	      sync_config.syncMode = sync_mode_;
113	      sync_config.irTriggerSignalInDelay = ir_trigger_signal_in_delay_;
114	      sync_config.rgbTriggerSignalInDelay = rgb_trigger_signal_in_delay_;
115	      sync_config.deviceTriggerSignalOutDelay = device_trigger_signal_out_delay_;
116	      device_->setSyncConfig(sync_config);
117	      // TODO: add set signal trigger out mode
118	    }
119	    if (info->pid() == GEMINI2_PID) {
120	      auto default_precision_level = device_->getIntProperty(OB_PROP_DEPTH_PRECISION_LEVEL_INT);
121	      if (default_precision_level != depth_precision_) {
122	        device_->setIntProperty(OB_PROP_DEPTH_PRECISION_LEVEL_INT, depth_precision_);
123	      }
124	    }
125	
126	    device_->setBoolProperty(OB_PROP_DEPTH_SOFT_FILTER_BOOL, enable_soft_filter_);
127	    device_->setBoolProperty(OB_PROP_COLOR_AUTO_EXPOSURE_BOOL, enable_color_auto_exposure_);
128	    device_->setBoolProperty(OB_PROP_IR_AUTO_EXPOSURE_BOOL, enable_ir_auto_exposure_);
129	    auto default_soft_filter_max_diff = device_->getIntProperty(OB_PROP_DEPTH_MAX_DIFF_INT);
130	    if (soft_filter_max_diff_ != -1 && default_soft_filter_max_diff != soft_filter_max_diff_) {
131	      device_->setIntProperty(OB_PROP_DEPTH_MAX_DIFF_INT, soft_filter_max_diff_);
132	    }
133	    auto default_soft_filter_speckle_size =
134	        device_->getIntProperty(OB_PROP_DEPTH_MAX_SPECKLE_SIZE_INT);
135	    if (soft_filter_speckle_size_ != -1 &&
136	        default_soft_filter_speckle_size != soft_filter_speckle_size_) {
137	      device_->setIntProperty(OB_PROP_DEPTH_MAX_SPECKLE_SIZE_INT, soft_filter_speckle_size_);
138	    }
139	  } catch (const ob::Error& e) {
140	    RCLCPP_ERROR_STREAM(logger_, "Failed to setup devices: " << e.getMessage());
141	  } catch (const std::exception& e) {
142	    RCLCPP_ERROR_STREAM(logger_, "Failed to setup devices: " << e.what());
143	  }
144	}
