146	void OBCameraNode::setupProfiles() {
147	  for (const auto& elem : IMAGE_STREAMS) {
148	    if (enable_stream_[elem]) {
149	      const auto& sensor = sensors_[elem];
150	      CHECK_NOTNULL(sensor.get());
151	      auto profiles = sensor->getStreamProfileList();
152	      CHECK_NOTNULL(profiles.get());
153	      CHECK(profiles->count() > 0);
154	      for (size_t i = 0; i < profiles->count(); i++) {
155	        auto profile = profiles->getProfile(i)->as<ob::VideoStreamProfile>();
156	        RCLCPP_DEBUG_STREAM(
157	            logger_, "Sensor profile: "
158	                         << "stream_type: " << magic_enum::enum_name(profile->type())
159	                         << "Format: " << profile->format() << ", Width: " << profile->width()
160	                         << ", Height: " << profile->height() << ", FPS: " << profile->fps());
161	        supported_profiles_[elem].emplace_back(profile);
162	      }
163	      std::shared_ptr<ob::VideoStreamProfile> selected_profile;
164	      std::shared_ptr<ob::VideoStreamProfile> default_profile;
165	      try {
166	        selected_profile =
167	            profiles->getVideoStreamProfile(width_[elem], height_[elem], format_[elem], fps_[elem]);
168	        default_profile =
169	            profiles->getVideoStreamProfile(width_[elem], height_[elem], format_[elem]);
170	      } catch (const ob::Error& ex) {
171	        RCLCPP_ERROR_STREAM(logger_, "Failed to get profile: " << ex.getMessage());
172	        RCLCPP_ERROR_STREAM(
173	            logger_, "Stream: " << magic_enum::enum_name(elem.first)
174	                                << ", Stream Index: " << elem.second << ", Width: " << width_[elem]
175	                                << ", Height: " << height_[elem] << ", FPS: " << fps_[elem]
176	                                << ", Format: " << magic_enum::enum_name(format_[elem]));
177	        throw;
178	      }
179	
180	      if (!selected_profile) {
181	        RCLCPP_WARN_STREAM(logger_, "Given stream configuration is not supported by the device! "
182	                                        << " Stream: " << magic_enum::enum_name(elem.first)
183	                                        << ", Stream Index: " << elem.second
184	                                        << ", Width: " << width_[elem]
185	                                        << ", Height: " << height_[elem] << ", FPS: " << fps_[elem]
186	                                        << ", Format: " << magic_enum::enum_name(format_[elem]));
187	        if (default_profile) {
188	          RCLCPP_WARN_STREAM(logger_, "Using default profile instead.");
189	          RCLCPP_WARN_STREAM(logger_, "default FPS " << default_profile->fps());
190	          selected_profile = default_profile;
191	        } else {
192	          RCLCPP_ERROR_STREAM(
193	              logger_, " NO default_profile found , Stream: " << magic_enum::enum_name(elem.first)
194	                                                              << " will be disable");
195	          enable_stream_[elem] = false;
196	          continue;
197	        }
198	      }
199	      CHECK_NOTNULL(selected_profile);
200	      stream_profile_[elem] = selected_profile;
201	      images_[elem] =
202	          cv::Mat(height_[elem], width_[elem], image_format_[elem], cv::Scalar(0, 0, 0));
203	      RCLCPP_INFO_STREAM(
204	          logger_, " stream " << stream_name_[elem] << " is enabled - width: " << width_[elem]
205	                              << ", height: " << height_[elem] << ", fps: " << fps_[elem] << ", "
206	                              << "Format: " << magic_enum::enum_name(selected_profile->format()));
207	    }
208	  }
209	}
