211	void OBCameraNode::startStreams() {
212	  if (pipeline_ != nullptr) {
213	    pipeline_.reset();
214	  }
215	  pipeline_ = std::make_unique<ob::Pipeline>(device_);
216	  try {
217	    setupPipelineConfig();
218	    pipeline_->start(pipeline_config_, [this](std::shared_ptr<ob::FrameSet> frame_set) {
219	      onNewFrameSetCallback(frame_set);
220	    });
221	  } catch (const ob::Error& e) {
222	    RCLCPP_ERROR_STREAM(logger_, "Failed to start pipeline: " << e.getMessage());
223	    RCLCPP_INFO_STREAM(logger_, "try to disable ir stream and try again");
224	    enable_stream_[INFRA0] = false;
225	    setupPipelineConfig();
226	    pipeline_->start(pipeline_config_, [this](std::shared_ptr<ob::FrameSet> frame_set) {
227	      onNewFrameSetCallback(frame_set);
228	    });
229	  }
230	  pipeline_started_.store(true);
231	  // startIMU();
232	}
