234	void OBCameraNode::startIMU() {
235	  for (const auto& stream_index : HID_STREAMS) {
236	    if (enable_stream_[stream_index]) {
237	      CHECK(sensors_.count(stream_index));
238	      auto profile_list = sensors_[stream_index]->getStreamProfileList();
239	      for (size_t i = 0; i < profile_list->count(); i++) {
240	        auto item = profile_list->getProfile(i);
241	        if (stream_index == ACCEL) {
242	          auto profile = item->as<ob::AccelStreamProfile>();
243	          auto accel_rate = sampleRateFromString(imu_rate_[stream_index]);
244	          auto accel_range = fullAccelScaleRangeFromString(imu_range_[stream_index]);
245	          if (profile->fullScaleRange() == accel_range && profile->sampleRate() == accel_rate) {
246	            sensors_[stream_index]->start(profile,
247	                                          [this, stream_index](std::shared_ptr<ob::Frame> frame) {
248	                                            onNewIMUFrameCallback(frame, stream_index);
249	                                          });
250	            imu_started_[stream_index] = true;
251	            RCLCPP_INFO_STREAM(logger_, "start accel stream with "
252	                                            << magic_enum::enum_name(accel_range) << " range and "
253	                                            << magic_enum::enum_name(accel_rate) << " rate");
254	          }
255	        } else if (stream_index == GYRO) {
256	          auto profile = item->as<ob::GyroStreamProfile>();
257	          auto gyro_rate = sampleRateFromString(imu_rate_[stream_index]);
258	          auto gyro_range = fullGyroScaleRangeFromString(imu_range_[stream_index]);
259	          if (profile->fullScaleRange() == gyro_range && profile->sampleRate() == gyro_rate) {
260	            sensors_[stream_index]->start(profile,
261	                                          [this, stream_index](std::shared_ptr<ob::Frame> frame) {
262	                                            onNewIMUFrameCallback(frame, stream_index);
263	                                          });
264	            RCLCPP_INFO_STREAM(logger_, "start gyro stream with "
265	                                            << magic_enum::enum_name(gyro_range) << " range and "
266	                                            << magic_enum::enum_name(gyro_rate) << " rate");
267	            imu_started_[stream_index] = true;
268	          }
269	        }
270	      }
271	    }
272	  }
273	  for (const auto& stream_index : HID_STREAMS) {
274	    if (enable_stream_[stream_index] && !imu_started_[stream_index]) {
275	      RCLCPP_ERROR_STREAM(logger_, "Failed to start IMU stream: "
276	                                       << magic_enum::enum_name(stream_index.first)
277	                                       << ", please check the imu_rate and imu_range parameters");
278	    }
279	  }
280	}
