282	void OBCameraNode::stopStreams() {
283	  if (!pipeline_started_ || !pipeline_) {
284	    return;
285	  }
286	  try {
287	    pipeline_->stop();
288	    // stopIMU();
289	  } catch (const ob::Error& e) {
290	    RCLCPP_ERROR_STREAM(logger_, "Failed to stop pipeline: " << e.getMessage());
291	  }
292	}
