294	void OBCameraNode::stopIMU() {
295	  for (const auto& stream_index : HID_STREAMS) {
296	    if (imu_started_[stream_index]) {
297	      CHECK(sensors_.count(stream_index));
298	      sensors_[stream_index]->stop();
299	      imu_started_[stream_index] = false;
300	    }
301	  }
302	}
