321	void OBCameraNode::getParameters() {
322	  setAndGetNodeParameter<std::string>(camera_name_, "camera_name", "camera");
323	  for (auto stream_index : IMAGE_STREAMS) {
324	    std::string param_name = stream_name_[stream_index] + "_width";
325	    setAndGetNodeParameter(width_[stream_index], param_name, IMAGE_WIDTH);
326	    param_name = stream_name_[stream_index] + "_height";
327	    setAndGetNodeParameter(height_[stream_index], param_name, IMAGE_HEIGHT);
328	    param_name = stream_name_[stream_index] + "_fps";
329	    setAndGetNodeParameter(fps_[stream_index], param_name, IMAGE_FPS);
330	    param_name = "enable_" + stream_name_[stream_index];
331	    setAndGetNodeParameter(enable_stream_[stream_index], param_name, false);
332	    param_name = camera_name_ + "_" + stream_name_[stream_index] + "_frame_id";
333	    std::string default_frame_id = camera_name_ + "_" + stream_name_[stream_index] + "_frame";
334	    setAndGetNodeParameter(frame_id_[stream_index], param_name, default_frame_id);
335	    std::string default_optical_frame_id =
336	        camera_name_ + "_" + stream_name_[stream_index] + "_optical_frame";
337	    param_name = stream_name_[stream_index] + "_optical_frame_id";
338	    setAndGetNodeParameter(optical_frame_id_[stream_index], param_name, default_optical_frame_id);
339	    depth_aligned_frame_id_[stream_index] = stream_name_[COLOR] + "_optical_frame";
340	    param_name = stream_name_[stream_index] + "_format";
341	    setAndGetNodeParameter(format_str_[stream_index], param_name, format_str_[stream_index]);
342	    format_[stream_index] = OBFormatFromString(format_str_[stream_index]);
343	    if (format_[stream_index] == OB_FORMAT_Y8) {
344	      CHECK(stream_index.first != OB_STREAM_COLOR);
345	      image_format_[stream_index] = CV_8UC1;
346	      encoding_[stream_index] = stream_index.first == OB_STREAM_DEPTH
347	                                    ? sensor_msgs::image_encodings::TYPE_8UC1
348	                                    : sensor_msgs::image_encodings::MONO8;
349	      unit_step_size_[stream_index] = sizeof(uint8_t);
350	    }
351	    param_name = stream_name_[stream_index] + "_qos";
352	    setAndGetNodeParameter<std::string>(image_qos_[stream_index], param_name, "default");
353	    param_name = stream_name_[stream_index] + "_camera_info_qos";
354	    setAndGetNodeParameter<std::string>(camera_info_qos_[stream_index], param_name, "default");
355	  }
356	
357	  for (const auto& stream_index : HID_STREAMS) {
358	    std::string param_name = stream_name_[stream_index] + "_qos";
359	    setAndGetNodeParameter<std::string>(imu_qos_[stream_index], param_name, "default");
360	    param_name = "enable_" + stream_name_[stream_index];
361	    setAndGetNodeParameter(enable_stream_[stream_index], param_name, false);
362	    param_name = stream_name_[stream_index] + "_rate";
363	    setAndGetNodeParameter<std::string>(imu_rate_[stream_index], param_name, "");
364	    param_name = stream_name_[stream_index] + "_range";
365	    setAndGetNodeParameter<std::string>(imu_range_[stream_index], param_name, "");
366	    param_name = camera_name_ + "_" + stream_name_[stream_index] + "_frame_id";
367	    std::string default_frame_id = camera_name_ + "_" + stream_name_[stream_index] + "_frame";
368	    setAndGetNodeParameter(frame_id_[stream_index], param_name, default_frame_id);
369	    std::string default_optical_frame_id =
370	        camera_name_ + "_" + stream_name_[stream_index] + "_optical_frame";
371	    param_name = stream_name_[stream_index] + "_optical_frame_id";
372	    setAndGetNodeParameter(optical_frame_id_[stream_index], param_name, default_optical_frame_id);
373	    depth_aligned_frame_id_[stream_index] = stream_name_[COLOR] + "_optical_frame";
374	  }
375	
376	  setAndGetNodeParameter(publish_tf_, "publish_tf", true);
377	  setAndGetNodeParameter(tf_publish_rate_, "tf_publish_rate", 10.0);
378	  setAndGetNodeParameter(depth_registration_, "depth_registration", false);
