507	void OBCameraNode::publishDepthPointCloud(const std::shared_ptr<ob::FrameSet>& frame_set) {
508	  if (!enable_point_cloud_ || !depth_cloud_pub_ ||
509	      depth_cloud_pub_->get_subscription_count() == 0) {
510	    return;
511	  }
512	  if (!camera_param_ && depth_registration_) {
513	    camera_param_ = pipeline_->getCameraParam();
514	  } else if (!camera_param_) {
515	    camera_param_ = getDepthCameraParam();
516	  }
517	  point_cloud_filter_.setCameraParam(*camera_param_);
518	  point_cloud_filter_.setCreatePointFormat(OB_FORMAT_POINT);
519	  auto depth_frame = frame_set->depthFrame();
520	  if (!depth_frame) {
521	    return;
522	  }
523	  auto frame = point_cloud_filter_.process(frame_set);
524	  if (!frame) {
525	    RCLCPP_ERROR_STREAM(logger_, "point cloud filter process failed");
526	    return;
527	  }
528	  size_t point_size = frame->dataSize() / sizeof(OBPoint);
529	  auto* points = (OBPoint*)frame->data();
530	  if (!points) {
531	    RCLCPP_ERROR_STREAM(logger_, "point cloud data is null");
532	    return;
533	  }
534	  CHECK_NOTNULL(points);
535	  sensor_msgs::PointCloud2Modifier modifier(point_cloud_msg_);
536	  modifier.setPointCloud2FieldsByString(1, "xyz");
537	  modifier.resize(point_size);
538	  point_cloud_msg_.width = depth_frame->width();
539	  point_cloud_msg_.height = depth_frame->height();
540	  point_cloud_msg_.row_step = point_cloud_msg_.width * point_cloud_msg_.point_step;
541	  point_cloud_msg_.data.resize(point_cloud_msg_.height * point_cloud_msg_.row_step);
542	  sensor_msgs::PointCloud2Iterator<float> iter_x(point_cloud_msg_, "x");
543	  sensor_msgs::PointCloud2Iterator<float> iter_y(point_cloud_msg_, "y");
544	  sensor_msgs::PointCloud2Iterator<float> iter_z(point_cloud_msg_, "z");
545	  size_t valid_count = 0;
546	  auto scale = depth_frame->getValueScale();
547	  for (size_t point_idx = 0; point_idx < point_size; point_idx++, points++) {
548	    bool valid_pixel(points->z > 0);
549	    if (valid_pixel) {
550	      *iter_x = static_cast<float>((points->x * scale) / 1000.0);
551	      *iter_y = -static_cast<float>((points->y * scale) / 1000.0);
552	      *iter_z = static_cast<float>((points->z * scale) / 1000.0);
553	      ++iter_x;
554	      ++iter_y;
555	      ++iter_z;
556	      ++valid_count;
557	    }
558	  }
559	  auto timestamp = frameTimeStampToROSTime(depth_frame->systemTimeStamp());
560	  point_cloud_msg_.header.stamp = timestamp;
561	  point_cloud_msg_.header.frame_id = optical_frame_id_[DEPTH];
562	  point_cloud_msg_.is_dense = true;
563	  point_cloud_msg_.width = valid_count;
564	  point_cloud_msg_.height = 1;
565	  modifier.resize(valid_count);
566	  depth_cloud_pub_->publish(point_cloud_msg_);
567	
568	  if (save_point_cloud_) {
569	    save_point_cloud_ = false;
570	    auto now = std::time(nullptr);
571	    std::stringstream ss;
572	    ss << std::put_time(std::localtime(&now), "%Y%m%d_%H%M%S");
573	    auto current_path = std::filesystem::current_path().string();
574	    std::string filename = current_path + "/point_cloud/points_" + ss.str() + ".ply";
575	    if (!std::filesystem::exists(current_path + "/point_cloud")) {
576	      std::filesystem::create_directory(current_path + "/point_cloud");
577	    }
578	    RCLCPP_INFO_STREAM(logger_, "Saving point cloud to " << filename);
579	    savePointsToPly(frame, filename);
580	  }
581	}
