583	void OBCameraNode::publishColoredPointCloud(const std::shared_ptr<ob::FrameSet>& frame_set) {
584	  if (!enable_colored_point_cloud_ || !depth_registration_cloud_pub_ ||
585	      depth_registration_cloud_pub_->get_subscription_count() == 0) {
586	    return;
587	  }
588	  auto depth_frame = frame_set->depthFrame();
589	  auto color_frame = frame_set->colorFrame();
590	  if (!depth_frame || !color_frame) {
591	    return;
592	  }
593	  if (!camera_param_) {
594	    camera_param_ = pipeline_->getCameraParam();
595	  }
596	  point_cloud_filter_.setCameraParam(*camera_param_);
597	  point_cloud_filter_.setCreatePointFormat(OB_FORMAT_POINT);
598	  point_cloud_filter_.setCreatePointFormat(OB_FORMAT_RGB_POINT);
599	  auto frame = point_cloud_filter_.process(frame_set);
600	  if (!frame) {
601	    RCLCPP_ERROR_STREAM(logger_, "point cloud filter process failed");
602	    return;
603	  }
604	  size_t point_size = frame->dataSize() / sizeof(OBColorPoint);
605	  auto* points = (OBColorPoint*)frame->data();
606	  if (!points) {
607	    RCLCPP_ERROR_STREAM(logger_, "point cloud data is null");
608	    return;
609	  }
610	  CHECK_NOTNULL(points);
611	  sensor_msgs::PointCloud2Modifier modifier(point_cloud_msg_);
612	  modifier.setPointCloud2FieldsByString(1, "xyz");
613	  modifier.resize(point_size);
614	  point_cloud_msg_.width = color_frame->width();
615	  point_cloud_msg_.height = color_frame->height();
616	  std::string format_str = "rgb";
617	  point_cloud_msg_.point_step =
618	      addPointField(point_cloud_msg_, format_str, 1, sensor_msgs::msg::PointField::FLOAT32,
619	                    point_cloud_msg_.point_step);
620	  point_cloud_msg_.row_step = point_cloud_msg_.width * point_cloud_msg_.point_step;
621	  point_cloud_msg_.data.resize(point_cloud_msg_.height * point_cloud_msg_.row_step);
622	  sensor_msgs::PointCloud2Iterator<float> iter_x(point_cloud_msg_, "x");
623	  sensor_msgs::PointCloud2Iterator<float> iter_y(point_cloud_msg_, "y");
624	  sensor_msgs::PointCloud2Iterator<float> iter_z(point_cloud_msg_, "z");
625	  sensor_msgs::PointCloud2Iterator<uint8_t> iter_r(point_cloud_msg_, "r");
626	  sensor_msgs::PointCloud2Iterator<uint8_t> iter_g(point_cloud_msg_, "g");
627	  sensor_msgs::PointCloud2Iterator<uint8_t> iter_b(point_cloud_msg_, "b");
628	  size_t valid_count = 0;
629	  auto scale = depth_frame->getValueScale();
630	  for (size_t point_idx = 0; point_idx < point_size; point_idx += 1) {
631	    bool valid_pixel((points + point_idx)->z > 0);
632	    if (valid_pixel) {
633	      *iter_x = static_cast<float>(((points + point_idx)->x * scale) / 1000.0);
634	      *iter_y = -static_cast<float>(((points + point_idx)->y * scale) / 1000.0);
635	      *iter_z = static_cast<float>(((points + point_idx)->z * scale) / 1000.0);
636	      *iter_r = static_cast<uint8_t>((points + point_idx)->r);
637	      *iter_g = static_cast<uint8_t>((points + point_idx)->g);
638	      *iter_b = static_cast<uint8_t>((points + point_idx)->b);
639	
640	      ++iter_x;
641	      ++iter_y;
642	      ++iter_z;
643	      ++iter_r;
644	      ++iter_g;
645	      ++iter_b;
646	      ++valid_count;
647	    }
648	  }
649	  auto timestamp = frameTimeStampToROSTime(depth_frame->systemTimeStamp());
650	  point_cloud_msg_.header.stamp = timestamp;
651	  point_cloud_msg_.header.frame_id = optical_frame_id_[COLOR];
652	  point_cloud_msg_.is_dense = true;
653	  point_cloud_msg_.width = valid_count;
654	  point_cloud_msg_.height = 1;
655	  modifier.resize(valid_count);
656	  depth_registration_cloud_pub_->publish(point_cloud_msg_);
657	  if (save_colored_point_cloud_) {
658	    save_colored_point_cloud_ = false;
659	    auto now = std::time(nullptr);
660	    std::stringstream ss;
661	    ss << std::put_time(std::localtime(&now), "%Y%m%d_%H%M%S");
662	    auto current_path = std::filesystem::current_path().string();
663	    std::string filename = current_path + "/point_cloud/colored_points_" + ss.str() + ".ply";
664	    if (!std::filesystem::exists(current_path + "/point_cloud")) {
665	      std::filesystem::create_directory(current_path + "/point_cloud");
666	    }
667	    RCLCPP_INFO_STREAM(logger_, "Saving point cloud to " << filename);
668	    saveRGBPointsToPly(frame, filename);
669	  }
