693	void OBCameraNode::onNewFrameCallback(const std::shared_ptr<ob::Frame>& frame,
694	                                      const stream_index_pair& stream_index) {
695	  if (frame == nullptr) {
696	    return;
697	  }
698	  std::shared_ptr<ob::VideoFrame> video_frame;
699	  if (frame->type() == OB_FRAME_COLOR && frame->format() != OB_FORMAT_RGB888) {
700	    if (!setupFormatConvertType(frame->format())) {
701	      RCLCPP_ERROR(logger_, "Unsupported color format: %d", frame->format());
702	      return;
703	    }
704	    auto color_frame = format_convert_filter_.process(frame);
705	    if (color_frame == nullptr) {
706	      RCLCPP_ERROR_SKIPFIRST_THROTTLE(logger_, *(node_->get_clock()), 1000,
707	                                      "Failed to convert frame to RGB format");
708	      return;
709	    }
710	    video_frame = color_frame->as<ob::ColorFrame>();
711	  } else if (frame->type() == OB_FRAME_COLOR) {
712	    video_frame = frame->as<ob::ColorFrame>();
713	  } else if (frame->type() == OB_FRAME_DEPTH) {
714	    video_frame = frame->as<ob::DepthFrame>();
715	  } else if (frame->type() == OB_FRAME_IR) {
716	    video_frame = frame->as<ob::IRFrame>();
717	  } else {
718	    RCLCPP_ERROR(logger_, "Unsupported frame type: %d", frame->type());
719	    return;

720	  }
721	  if (!video_frame) {
722	    RCLCPP_ERROR(logger_, "Failed to convert frame to video frame");
723	    return;
724	  }
725	  int width = static_cast<int>(video_frame->width());
726	  int height = static_cast<int>(video_frame->height());
727	  auto& image = images_[stream_index];
728	  if (image.empty() || image.cols != width || image.rows != height) {
729	    image.create(height, width, image_format_[stream_index]);
730	  }
731	  image.data = (uchar*)video_frame->data();
732	  if (stream_index == DEPTH) {
733	    auto depth_scale = video_frame->as<ob::DepthFrame>()->getValueScale();
734	    image = image * depth_scale;
735	  }
736	
737	  auto timestamp = frameTimeStampToROSTime(video_frame->systemTimeStamp());
738	  if (!camera_param_ && depth_registration_) {
739	    camera_param_ = pipeline_->getCameraParam();
740	  } else if (!camera_param_ && stream_index == COLOR) {
741	    camera_param_ = getColorCameraParam();
742	  } else if (!camera_param_ && (stream_index == DEPTH || stream_index == INFRA0)) {
743	    camera_param_ = getDepthCameraParam();
744	  }
745	  auto& intrinsic =
746	      stream_index == COLOR ? camera_param_->rgbIntrinsic : camera_param_->depthIntrinsic;
747	  auto& distortion =
748	      stream_index == COLOR ? camera_param_->rgbDistortion : camera_param_->depthDistortion;
749	  auto camera_info = convertToCameraInfo(intrinsic, distortion, width);
750	  CHECK(camera_info_publishers_.count(stream_index) > 0);
751	  camera_info_publishers_[stream_index]->publish(camera_info);
752	  auto image_msg =
753	      cv_bridge::CvImage(std_msgs::msg::Header(), encoding_[stream_index], image).toImageMsg();
754	  image_msg->header.stamp = timestamp;
755	  image_msg->is_bigendian = false;
756	  image_msg->step = width * unit_step_size_[stream_index];
757	  image_msg->header.frame_id =
758	      depth_registration_ ? depth_aligned_frame_id_[stream_index] : optical_frame_id_[stream_index];
759	  CHECK(image_publishers_.count(stream_index) > 0);
760	  image_publishers_[stream_index].publish(image_msg);
761	  saveImageToFile(stream_index, image, image_msg);
762	}
