764	void OBCameraNode::saveImageToFile(const stream_index_pair& stream_index, const cv::Mat& image,
765	                                   const sensor_msgs::msg::Image::SharedPtr& image_msg) {
766	  if (save_images_[stream_index]) {
767	    auto now = time(nullptr);
768	    std::stringstream ss;
769	    ss << std::put_time(localtime(&now), "%Y%m%d_%H%M%S");
770	    auto current_path = std::filesystem::current_path().string();
771	    auto fps = fps_[stream_index];
772	    std::string filename = current_path + "/image/" + stream_name_[stream_index] + "_" +
773	                           std::to_string(image_msg->width) + "x" +
774	                           std::to_string(image_msg->height) + "_" + std::to_string(fps) + "hz_" +
775	                           ss.str() + ".png";
776	    if (!std::filesystem::exists(current_path + "/image")) {
777	      std::filesystem::create_directory(current_path + "/image");
778	    }
779	    RCLCPP_INFO_STREAM(logger_, "Saving image to " << filename);
780	    if (stream_index.first == OB_STREAM_DEPTH) {
781	      auto image_to_save = cv_bridge::toCvCopy(image_msg, encoding_[stream_index])->image;
782	      cv::imwrite(filename, image_to_save);
783	    } else if (stream_index.first == OB_STREAM_COLOR) {
784	      auto image_to_save =
785	          cv_bridge::toCvCopy(image_msg, sensor_msgs::image_encodings::BGR8)->image;
786	      cv::imwrite(filename, image_to_save);
787	    } else if (stream_index.first == OB_STREAM_IR) {
788	      cv::imwrite(filename, image);
789	    } else {
790	      RCLCPP_ERROR_STREAM(logger_, "Unsupported stream type: " << stream_index.first);
791	    }
792	    save_images_[stream_index] = false;
793	  }
794	}
