796	void OBCameraNode::onNewIMUFrameCallback(const std::shared_ptr<ob::Frame>& frame,
797	                                         const stream_index_pair& stream_index) {
798	  if (!imu_publishers_.count(stream_index)) {
799	    RCLCPP_ERROR_STREAM(logger_,
800	                        "stream " << stream_name_[stream_index] << " publisher not initialized");
801	    return;
802	  }
803	  auto subscriber_count = imu_publishers_[stream_index]->get_subscription_count();
804	  if (subscriber_count == 0) {
805	    return;
806	  }
807	  auto imu_msg = sensor_msgs::msg::Imu();
808	  setDefaultIMUMessage(imu_msg);
809	  imu_msg.header.frame_id = optical_frame_id_[stream_index];
810	  auto timestamp = frameTimeStampToROSTime(frame->systemTimeStamp());
811	  imu_msg.header.stamp = timestamp;
812	  if (frame->type() == OB_FRAME_GYRO) {
813	    auto gyro_frame = frame->as<ob::GyroFrame>();
