902	void OBCameraNode::publishStaticTF(const rclcpp::Time& t, const std::vector<float>& trans,
903	                                   const tf2::Quaternion& q, const std::string& from,
904	                                   const std::string& to) {
905	  CHECK_EQ(trans.size(), 3u);
906	  geometry_msgs::msg::TransformStamped msg;
907	  msg.header.stamp = t;
908	  msg.header.frame_id = from;
909	  msg.child_frame_id = to;
910	  msg.transform.translation.x = trans.at(2) / 1000.0;
911	  msg.transform.translation.y = -trans.at(0) / 1000.0;
912	  msg.transform.translation.z = -trans.at(1) / 1000.0;
913	  msg.transform.rotation.x = q.getX();
914	  msg.transform.rotation.y = q.getY();
915	  msg.transform.rotation.z = q.getZ();
916	  msg.transform.rotation.w = q.getW();
917	  static_tf_msgs_.push_back(msg);
