167	void OBCameraNodeDriver::releaseDeviceSemaphore(sem_t *device_sem, int &num_devices_connected) {
168	  RCLCPP_INFO_THROTTLE(logger_, *get_clock(), 1000, "Release device semaphore");
169	  sem_post(device_sem);
170	  int sem_value = 0;
171	  sem_getvalue(device_sem, &sem_value);
172	  RCLCPP_INFO_STREAM_THROTTLE(logger_, *get_clock(), 1000, "semaphore value: " << sem_value);
173	  RCLCPP_INFO_THROTTLE(logger_, *get_clock(), 1000, "Release device semaphore done");
174	  if (num_devices_connected >= device_num_) {
175	    sem_destroy(device_sem);
