180	void OBCameraNodeDriver::updateConnectedDeviceCount(int &num_devices_connected,
181	                                                    DeviceConnectionEvent connection_event) {
182	  // write connected device count to file
183	  int shm_id = shmget(DEFAULT_SEM_KEY, 1, 0666 | IPC_CREAT);
184	  if (shm_id == -1) {
185	    RCLCPP_INFO_STREAM(logger_, "Failed to create shared memory " << strerror(errno));
186	    return;
187	  }
188	  auto shm_ptr = (int *)shmat(shm_id, nullptr, 0);
189	  if (shm_ptr == (void *)-1) {
190	    RCLCPP_INFO_STREAM(logger_, "Failed to attach shared memory " << strerror(errno));
191	    return;
192	  }
193	  if (connection_event == DeviceConnectionEvent::kDeviceConnected) {
194	    num_devices_connected = *shm_ptr + 1;
195	  } else if (connection_event == DeviceConnectionEvent::kDeviceDisconnected && *shm_ptr > 0) {
196	    num_devices_connected = *shm_ptr - 1;
197	  } else {
198	    num_devices_connected = *shm_ptr;
199	  }
200	  RCLCPP_DEBUG_STREAM_THROTTLE(logger_, *get_clock(), 5000,
201	                               "Current connected device " << num_devices_connected);
202	  *shm_ptr = static_cast<int>(num_devices_connected);
203	  shmdt(shm_ptr);
204	  if (connection_event == DeviceConnectionEvent::kDeviceDisconnected &&
205	      num_devices_connected == 0) {
206	    shmctl(shm_id, IPC_RMID, nullptr);
207	    sem_unlink(DEFAULT_SEM_NAME.c_str());
208	  }
209	}
