211	std::shared_ptr<ob::Device> OBCameraNodeDriver::selectDevice(
212	    const std::shared_ptr<ob::DeviceList> &list) {
213	  if (device_num_ == 1) {
214	    RCLCPP_INFO_STREAM(logger_, "Connecting to the default device");
215	    return list->getDevice(0);
216	  }
217	  sem_t *device_sem = sem_open(DEFAULT_SEM_NAME.c_str(), O_CREAT, 0644, 1);
218	  if (device_sem == SEM_FAILED) {
219	    RCLCPP_INFO_STREAM(logger_, "Failed to open semaphore");
220	    return nullptr;
221	  }
222	  RCLCPP_INFO_STREAM_THROTTLE(logger_, *get_clock(), 1000,
223	                              "Connecting to device with serial number: " << serial_number_);
224	  int sem_value = 0;
225	  sem_getvalue(device_sem, &sem_value);
226	  RCLCPP_INFO_STREAM_THROTTLE(logger_, *get_clock(), 1000, "semaphore value: " << sem_value);
227	  int ret = sem_wait(device_sem);
228	  if (ret != 0) {
229	    RCLCPP_ERROR_STREAM(logger_, "Failed to wait semaphore " << strerror(errno));
230	    releaseDeviceSemaphore(device_sem, num_devices_connected_);
231	    return nullptr;
232	  }
233	  auto device = selectDeviceBySerialNumber(list, serial_number_);
234	  std::shared_ptr<int> sem_guard(nullptr, [&, device](int const *) {
235	    auto connect_event = device != nullptr ? DeviceConnectionEvent::kDeviceConnected
236	                                           : DeviceConnectionEvent::kOtherDeviceConnected;
237	    updateConnectedDeviceCount(num_devices_connected_, connect_event);
238	
239	    releaseDeviceSemaphore(device_sem, num_devices_connected_);
240	  });
241	  if (device == nullptr) {
242	    RCLCPP_WARN_THROTTLE(logger_, *get_clock(), 1000, "Device with serial number %s not found",
243	                         serial_number_.c_str());
244	    device_connected_ = false;
245	    return nullptr;
246	  }
247	  return device;
248	}
249	
250	std::shared_ptr<ob::Device> OBCameraNodeDriver::selectDeviceBySerialNumber(
251	    const std::shared_ptr<ob::DeviceList> &list, const std::string &serial_number) {
252	  std::string lower_sn;
253	  std::transform(serial_number.begin(), serial_number.end(), std::back_inserter(lower_sn),
254	                 [](auto ch) { return isalpha(ch) ? tolower(ch) : static_cast<int>(ch); });
255	  for (size_t i = 0; i < list->deviceCount(); i++) {
256	    try {
257	      auto pid = list->pid(i);
258	      if (isOpenNIDevice(pid)) {
259	        // openNI device
260	        auto device = list->getDevice(i);
261	        auto device_info = device->getDeviceInfo();
262	        if (device_info->serialNumber() == serial_number) {
263	          RCLCPP_INFO_STREAM(logger_,
264	                             "Device serial number " << device_info->serialNumber() << " matched");
265	          return device;
266	        }
267	      } else {
268	        std::string sn = list->serialNumber(i);
269	        RCLCPP_INFO_STREAM_THROTTLE(logger_, *get_clock(), 1000, "Device serial number: " << sn);
270	        if (sn == serial_number) {
271	          RCLCPP_INFO_STREAM(logger_, "Device serial number " << sn << " matched");
272	          return list->getDevice(i);
273	        }
274	      }
275	    } catch (ob::Error &e) {
276	      RCLCPP_ERROR_STREAM_THROTTLE(logger_, *get_clock(), 1000,
277	                                   "Failed to get device info " << e.getMessage());
278	    } catch (std::exception &e) {
279	      RCLCPP_ERROR_STREAM(logger_, "Failed to get device info " << e.what());
280	    } catch (...) {
281	      RCLCPP_ERROR_STREAM(logger_, "Failed to get device info");
282	    }
283	  }
284	  return nullptr;
285	}
