287	void OBCameraNodeDriver::initializeDevice(const std::shared_ptr<ob::Device> &device) {
288	  device_ = device;
289	  CHECK_NOTNULL(device_);
290	  CHECK_NOTNULL(device_.get());
291	  if (ob_camera_node_) {
292	    ob_camera_node_.reset();
293	  }
294	  ob_camera_node_ = std::make_unique<OBCameraNode>(this, device_, parameters_);
295	  device_connected_ = true;
296	  device_info_ = device_->getDeviceInfo();
297	  CHECK_NOTNULL(device_info_.get());
298	  device_unique_id_ = device_info_->uid();
299	  RCLCPP_INFO_STREAM(logger_, "Device " << device_info_->name() << " connected");
300	  RCLCPP_INFO_STREAM(logger_, "Serial number: " << device_info_->serialNumber());
301	  RCLCPP_INFO_STREAM(logger_, "Firmware version: " << device_info_->firmwareVersion());
302	  RCLCPP_INFO_STREAM(logger_, "Hardware version: " << device_info_->hardwareVersion());
303	  RCLCPP_INFO_STREAM(logger_, "device type: " << ObDeviceTypeToString(device_info_->deviceType()));
304	  RCLCPP_INFO_STREAM(logger_, "device unique id: " << device_unique_id_);
305	}
306	
307	void OBCameraNodeDriver::startDevice(const std::shared_ptr<ob::DeviceList> &list) {
308	  std::scoped_lock<decltype(device_lock_)> lock(device_lock_);
309	  if (device_connected_) {
310	    return;
311	  }
312	  if (list->deviceCount() == 0) {
313	    RCLCPP_WARN(logger_, "No device found");
314	    return;
315	  }
316	  if (device_) {
317	    device_.reset();
318	  }
319	  auto device = selectDevice(list);
320	  if (device == nullptr) {
321	    RCLCPP_WARN_THROTTLE(logger_, *get_clock(), 1000, "Device with serial number %s not found",
322	                         serial_number_.c_str());
323	    device_connected_ = false;
324	    return;
325	  }
326	  initializeDevice(device);
327	}
