// ---------------------------------------------------------------------------

// Payload shared by (possibly several) ob::Frame views of the same data.
struct FramePayload {
  OBFrameType type = OB_FRAME_UNKNOWN;
  OBFormat format = OB_FORMAT_UNKNOWN;
  uint64_t index = 0;
  uint64_t system_time_ms = 0;   // host clock, milliseconds (matches SDK API)
  uint64_t time_stamp_us = 0;    // device timestamp when available
  uint32_t width = 0;
  uint32_t height = 0;
  float value_scale = 1.0f;      // DepthFrame::getValueScale
  OBFrameType data_source = OB_FRAME_IR;
  std::shared_ptr<std::vector<uint8_t>> data;
};

