// Logging, error, version and product database for the in-tree SDK.
#include "ob_internal.h"

#include <chrono>
#include <cstdarg>
#include <cstdio>
#include <cstring>
#include <ctime>
#include <iostream>
#include <sstream>

namespace obsdk {

namespace {
std::atomic<int> g_log_severity{static_cast<int>(OB_LOG_SEVERITY_NONE)};
}

void logSetSeverity(OBLogSeverity severity) { g_log_severity.store(static_cast<int>(severity)); }

OBLogSeverity logSeverity() { return static_cast<OBLogSeverity>(g_log_severity.load()); }

void logWrite(OBLogSeverity severity, const char *file, int line, const std::string &msg) {
  const char *base = file;
  if (const char *slash = std::strrchr(file, '/')) {
    base = slash + 1;
  }
  static const char *kNames[] = {"DEBUG", "INFO", "WARN", "ERROR", "FATAL", "NONE"};
  int idx = static_cast<int>(severity);
  if (idx < 0 || idx > 5) {
    idx = 1;
  }
  // std::cout avoids glog dependency; keep a single line per message.
  std::ostringstream out;
  out << "[" << kNames[idx] << "] " << base << ":" << line << " " << msg << "\n";
  fputs(out.str().c_str(), idx >= static_cast<int>(OB_LOG_SEVERITY_ERROR) ? stderr : stdout);
}

void throwError(const std::string &message) {
  OBSDK_ERROR("throw ob::Error: " << message);
  throw ob::Error(std::make_unique<ErrorImpl>(message));
}

void throwIf(bool condition, const std::string &message) {
  if (condition) {
    throwError(message);
  }
}

const ProductInfo *lookupProduct(uint16_t pid) {
  // Values from orbbec_camera/constants.h and the SDK device database.
  static const ProductInfo kProducts[] = {
      {0x0404, "Astra Mini", ProductClass::kAstraMini},
      {0x0407, "Astra Mini S", ProductClass::kAstraMini},
      {0x0601, "Orbbec Camera", ProductClass::kGenericOrbbec},
      {0x0635, "Femto", ProductClass::kFemto},
      {0x0636, "Astra Plus", ProductClass::kAstraPlus},
      {0x0637, "Astra Plus S", ProductClass::kAstraPlus},
      {0x0638, "Femto OW", ProductClass::kFemto},
      {0x0668, "Femto Live", ProductClass::kFemto},
      {0x0670, "Gemini2", ProductClass::kGemini2},
      // Gemini (depth 640x400 Y11, color 640x480 MJPG, IR 640x400 Y10).
      // The exact pid list is confirmed against the original SDK binary; all
      // other 0x2bc5 devices are accepted as generic Orbbec devices anyway.
      {0x063b, "Gemini", ProductClass::kGemini},
      {0x063d, "Gemini", ProductClass::kGemini},
      {0x063f, "Gemini", ProductClass::kGemini},
  };
  for (const auto &entry : kProducts) {
    if (entry.pid == pid) {
      return &entry;
    }
  }
  return nullptr;
}

}  // namespace obsdk

// ---------------------------------------------------------------------------
// ob::Error
// ---------------------------------------------------------------------------
struct ErrorImpl {
  std::string message;
  OBExceptionType type = OB_EXCEPTION_TYPE_UNKNOWN;
  std::string name = "ob::Error";
  std::string args;
  explicit ErrorImpl(std::string msg) : message(std::move(msg)) {}
};

namespace ob {

Error::Error(std::unique_ptr<ErrorImpl> impl) noexcept : impl_(std::move(impl)) {}

Error::Error(const Error &error) noexcept {
  if (error.impl_) {
    impl_ = std::make_unique<ErrorImpl>(*error.impl_);
  }
}

Error::~Error() noexcept = default;

const char *Error::getMessage() const noexcept {
  return impl_ ? impl_->message.c_str() : "";
}

OBExceptionType Error::getExceptionType() const noexcept {
  return impl_ ? impl_->type : OB_EXCEPTION_TYPE_UNKNOWN;
}

const char *Error::getName() const noexcept {
  return impl_ ? impl_->name.c_str() : "";
}

const char *Error::getArgs() const noexcept {
  return impl_ ? impl_->args.c_str() : "";
}

}  // namespace ob

// ---------------------------------------------------------------------------
// ob::Version
// ---------------------------------------------------------------------------
namespace ob {

int Version::getMajor() { return 1; }
int Version::getMinor() { return 5; }
int Version::getPatch() { return 7; }
int Version::getVersion() { return 10507; }

}  // namespace ob

