// ob::Frame family implementation.
#include "ob_internal.h"

#include <cstring>

namespace obsdk {

std::shared_ptr<ob::Frame> makeFrame(const RawFrame &raw) {
  auto impl = std::make_unique<FrameImpl>();
  impl->payload.type = raw.type;
  impl->payload.format = raw.format;
  impl->payload.width = raw.width;
  impl->payload.height = raw.height;
  impl->payload.system_time_ms = raw.system_time_ms;
  impl->payload.time_stamp_us = raw.time_stamp_us;
  impl->payload.data = raw.data;

  std::shared_ptr<ob::Frame> frame;
  switch (raw.type) {
    case OB_FRAME_COLOR:
      frame = std::make_shared<ob::ColorFrame>(*reinterpret_cast<ob::Frame *>(nullptr));  // unused
      break;
    default:
      break;
  }
  // The derived constructors require a base Frame reference, so build the base
  // first through a helper that owns it, then transfer into the derived type.
  frame.reset();
  auto base = std::make_shared<ob::Frame>(std::move(impl));
  switch (raw.type) {
    case OB_FRAME_COLOR:
      frame = std::make_shared<ob::ColorFrame>(*base);
      break;
    case OB_FRAME_DEPTH:
      frame = std::make_shared<ob::DepthFrame>(*base);
      break;
    case OB_FRAME_IR:
    case OB_FRAME_IR_LEFT:
    case OB_FRAME_IR_RIGHT:
      frame = std::make_shared<ob::IRFrame>(*base);
      break;
    case OB_FRAME_ACCEL:
      frame = std::make_shared<ob::AccelFrame>(*base);
      break;
    case OB_FRAME_GYRO:
      frame = std::make_shared<ob::GyroFrame>(*base);
      break;
    case OB_FRAME_SET:
      frame = std::make_shared<ob::FrameSet>(*base);
      break;
    case OB_FRAME_POINTS:
      frame = std::make_shared<ob::PointsFrame>(*base);
      break;
    default:
      frame = base;
      break;
  }
  return frame;
}

std::shared_ptr<ob::Frame> makeFrameSet(std::vector<std::shared_ptr<ob::Frame>> children,
                                        uint64_t system_time_ms) {
  auto impl = std::make_unique<FrameImpl>();
  impl->payload.type = OB_FRAME_SET;
  impl->payload.format = OB_FORMAT_UNKNOWN;
  impl->payload.system_time_ms = system_time_ms;
  impl->payload.frames = std::move(children);
  return std::make_shared<ob::FrameSet>(*reinterpret_cast<ob::Frame *>(nullptr));  // placeholder
}

}  // namespace obsdk

namespace ob {

// ---------------------------------------------------------------------------
// Frame
// ---------------------------------------------------------------------------
Frame::Frame(std::unique_ptr<FrameImpl> impl) : impl_(std::move(impl)) {}

Frame::Frame(Frame &frame) : impl_(frame.impl_ ? std::make_unique<FrameImpl>(*frame.impl_) : nullptr) {}

Frame::~Frame() noexcept = default;

OBFrameType Frame::type() { return impl_ ? impl_->payload.type : OB_FRAME_UNKNOWN; }

OBFormat Frame::format() { return impl_ ? impl_->payload.format : OB_FORMAT_UNKNOWN; }

uint64_t Frame::index() { return impl_ ? impl_->payload.index : 0; }

void *Frame::data() {
  return impl_ && impl_->payload.data ? static_cast<void *>(impl_->payload.data->data()) : nullptr;
}

uint32_t Frame::dataSize() {
  return impl_ && impl_->payload.data ? static_cast<uint32_t>(impl_->payload.data->size()) : 0;
}

uint64_t Frame::timeStamp() { return impl_ ? impl_->payload.time_stamp_us / 1000 : 0; }

uint64_t Frame::timeStampUs() { return impl_ ? impl_->payload.time_stamp_us : 0; }

uint64_t Frame::systemTimeStamp() { return impl_ ? impl_->payload.system_time_ms : 0; }

// ---------------------------------------------------------------------------
// VideoFrame family
// ---------------------------------------------------------------------------
VideoFrame::VideoFrame(Frame &frame) : Frame(frame) {}
VideoFrame::~VideoFrame() noexcept {}

uint32_t VideoFrame::width() { return impl_ ? impl_->payload.width : 0; }
uint32_t VideoFrame::height() { return impl_ ? impl_->payload.height : 0; }
void *VideoFrame::metadata() { return nullptr; }
uint32_t VideoFrame::metadataSize() { return 0; }

uint8_t VideoFrame::pixelAvailableBitSize() {
  if (!impl_) {
    return 0;
  }
  switch (impl_->payload.format) {
    case OB_FORMAT_Y16:
    case OB_FORMAT_Y14:
    case OB_FORMAT_Y12:
    case OB_FORMAT_Y11:
    case OB_FORMAT_Y10:
      return 16;
    case OB_FORMAT_Y8:
    case OB_FORMAT_MJPG:
      return 8;
    default:
      return 8;
  }
}

ColorFrame::ColorFrame(Frame &frame) : VideoFrame(frame) {}

DepthFrame::DepthFrame(Frame &frame) : VideoFrame(frame) {}

float DepthFrame::getValueScale() { return impl_ ? impl_->payload.value_scale : 1.0f; }

IRFrame::IRFrame(Frame &frame) : VideoFrame(frame) {}

OBSensorType IRFrame::getDataSource() {
  if (!impl_) {
    return OB_SENSOR_IR;
  }
  switch (impl_->payload.data_source) {
    case OB_FRAME_IR_LEFT:
      return OB_SENSOR_IR_LEFT;
    case OB_FRAME_IR_RIGHT:
      return OB_SENSOR_IR_RIGHT;
    default:
      return OB_SENSOR_IR;
  }
}

PointsFrame::PointsFrame(Frame &frame) : Frame(frame) {}
float PointsFrame::getPositionValueScale() { return impl_ ? impl_->payload.value_scale : 1.0f; }

// ---------------------------------------------------------------------------
// FrameSet
// ---------------------------------------------------------------------------
FrameSet::FrameSet(Frame &frame) : Frame(frame) {}

uint32_t FrameSet::frameCount() {
  return impl_ ? static_cast<uint32_t>(impl_->frames.size()) : 0;
}

namespace {
template <typename T>
std::shared_ptr<T> findChild(const std::unique_ptr<FrameImpl> &impl, OBFrameType type) {
  if (!impl) {
    return nullptr;
  }
  for (const auto &child : impl->frames) {
    if (child && child->type() == type) {
      return std::dynamic_pointer_cast<T>(child);
    }
  }
  return nullptr;
}
}  // namespace

std::shared_ptr<DepthFrame> FrameSet::depthFrame() { return findChild<DepthFrame>(impl_, OB_FRAME_DEPTH); }
std::shared_ptr<ColorFrame> FrameSet::colorFrame() { return findChild<ColorFrame>(impl_, OB_FRAME_COLOR); }
std::shared_ptr<IRFrame> FrameSet::irFrame() {
  auto frame = findChild<IRFrame>(impl_, OB_FRAME_IR);
  if (!frame) {
    frame = findChild<IRFrame>(impl_, OB_FRAME_IR_LEFT);
  }
  if (!frame) {
    frame = findChild<IRFrame>(impl_, OB_FRAME_IR_RIGHT);
  }
  return frame;
}
std::shared_ptr<PointsFrame> FrameSet::pointsFrame() {
  return findChild<PointsFrame>(impl_, OB_FRAME_POINTS);
}

std::shared_ptr<Frame> FrameSet::getFrame(OBFrameType frameType) {
  if (!impl_) {
    return nullptr;
  }
  for (const auto &child : impl->frames) {
    if (child && child->type() == frameType) {
      return child;
    }
  }
  return nullptr;
}

// ---------------------------------------------------------------------------
// IMU frames
// ---------------------------------------------------------------------------
AccelFrame::AccelFrame(Frame &frame) : Frame(frame) {}

OBAccelValue AccelFrame::value() {
  OBAccelValue v{0.f, 0.f, 0.f};
  if (impl_ && impl_->payload.data && impl_->payload.data->size() >= sizeof(OBAccelValue)) {
    std::memcpy(&v, impl_->payload.data->data(), sizeof(OBAccelValue));
  }
  return v;
}

float AccelFrame::temperature() {
  if (impl_ && impl_->payload.data &&
      impl_->payload.data->size() >= sizeof(OBAccelValue) + sizeof(float)) {
    float t = 0.f;
    std::memcpy(&t, impl_->payload.data->data() + sizeof(OBAccelValue), sizeof(float));
    return t;
  }
  return 0.f;
}

GyroFrame::GyroFrame(Frame &frame) : Frame(frame) {}

OBGyroValue GyroFrame::value() {
  OBGyroValue v{0.f, 0.f, 0.f};
  if (impl_ && impl_->payload.data && impl_->payload.data->size() >= sizeof(OBGyroValue)) {
    std::memcpy(&v, impl_->payload.data->data(), sizeof(OBGyroValue));
  }
  return v;
}

float GyroFrame::temperature() {
  if (impl_ && impl_->payload.data &&
      impl_->payload.data->size() >= sizeof(OBGyroValue) + sizeof(float)) {
    float t = 0.f;
    std::memcpy(&t, impl_->payload.data->data() + sizeof(OBGyroValue), sizeof(float));
    return t;
  }
  return 0.f;
}

// ---------------------------------------------------------------------------
// FrameHelper
// ---------------------------------------------------------------------------
FrameHelper::FrameHelper() {}
FrameHelper::~FrameHelper() {}

std::shared_ptr<Frame> FrameHelper::createFrameFromBuffer(OBFormat format, uint32_t width,
                                                          uint32_t height, uint8_t *buffer,
                                                          uint32_t bufferSize,
                                                          BufferDestroyCallback destroyCallback,
                                                          void *destroyCallbackContext) {
  auto impl = std::make_unique<FrameImpl>();
  impl->payload.format = format;
  impl->payload.width = width;
  impl->payload.height = height;
  impl->payload.type = OB_FRAME_VIDEO;
  if (destroyCallback) {
    impl->payload.data = std::shared_ptr<std::vector<uint8_t>>(
        new std::vector<uint8_t>(buffer, buffer + bufferSize), [destroyCallback, destroyCallbackContext,
                                                                buffer](std::vector<uint8_t> * /*unused*/) {
          destroyCallback(buffer, destroyCallbackContext);
        });
  } else {
    impl->payload.data = std::make_shared<std::vector<uint8_t>>(buffer, buffer + bufferSize);
  }
  return std::make_shared<Frame>(std::move(impl));
}

std::shared_ptr<Frame> FrameHelper::createFrameSet() {
  auto impl = std::make_unique<FrameImpl>();
  impl->payload.type = OB_FRAME_SET;
  return std::make_shared<FrameSet>(*reinterpret_cast<Frame *>(nullptr));  // replaced below
}

void FrameHelper::pushFrame(std::shared_ptr<Frame> frameSet, OBFrameType frameType,
                            std::shared_ptr<Frame> frame) {
  if (!frameSet || !frame) {
    return;
  }
  (void)frameType;
  // impl_ is protected; access through a friend-less trick: FrameHelper is
  // declared as friend of Frame in the public header.
  frameSet->impl_->frames.push_back(frame);
}

void FrameHelper::setFrameSystemTimestamp(std::shared_ptr<Frame> frame, uint64_t systemTimestamp) {
  if (frame && frame->impl_) {
    frame->impl_->payload.system_time_ms = systemTimestamp;
  }
}

void FrameHelper::setFrameDeviceTimestamp(std::shared_ptr<Frame> frame, uint64_t deviceTimestamp) {
  if (frame && frame->impl_) {
    frame->impl_->payload.time_stamp_us = deviceTimestamp * 1000;
  }
}

void FrameHelper::setFrameDeviceTimestampUs(std::shared_ptr<Frame> frame, uint64_t deviceTimestampUs) {
  if (frame && frame->impl_) {
    frame->impl_->payload.time_stamp_us = deviceTimestampUs;
  }
}

}  // namespace ob

