// ob::StreamProfile family implementation.
#include "ob_internal.h"

#include <algorithm>

namespace ob {

// ---------------------------------------------------------------------------
// StreamProfile
// ---------------------------------------------------------------------------
StreamProfile::StreamProfile(std::unique_ptr<StreamProfileImpl> impl) : impl_(std::move(impl)) {}

StreamProfile::StreamProfile(StreamProfile &streamProfile)
    : impl_(streamProfile.impl_ ? std::make_unique<StreamProfileImpl>(*streamProfile.impl_)
                                : nullptr) {}

OBFormat StreamProfile::format() const { return impl_ ? impl_->format : OB_FORMAT_UNKNOWN; }

OBStreamType StreamProfile::type() const { return impl_ ? impl_->stream_type : OB_STREAM_UNKNOWN; }

// ---------------------------------------------------------------------------
// VideoStreamProfile / IMU profiles
// ---------------------------------------------------------------------------
VideoStreamProfile::VideoStreamProfile(StreamProfile &profile) : StreamProfile(profile) {}

uint32_t VideoStreamProfile::fps() const { return impl_ ? impl_->fps : 0; }
uint32_t VideoStreamProfile::width() const { return impl_ ? impl_->width : 0; }
uint32_t VideoStreamProfile::height() const { return impl_ ? impl_->height : 0; }

AccelStreamProfile::AccelStreamProfile(StreamProfile &profile) : StreamProfile(profile) {}
OBAccelFullScaleRange AccelStreamProfile::fullScaleRange() const {
  return impl_ ? impl_->accel_range : OB_ACCEL_FS_8g;
}
OBAccelSampleRate AccelStreamProfile::sampleRate() const {
  return impl_ ? impl_->accel_rate : OB_SAMPLE_RATE_200_HZ;
}

GyroStreamProfile::GyroStreamProfile(StreamProfile &profile) : StreamProfile(profile) {}
OBGyroFullScaleRange GyroStreamProfile::fullScaleRange() const {
  return impl_ ? impl_->gyro_range : OB_GYRO_FS_500dps;
}
OBGyroSampleRate GyroStreamProfile::sampleRate() const {
  return impl_ ? impl_->gyro_rate : OB_SAMPLE_RATE_200_HZ;
}

// ---------------------------------------------------------------------------
// StreamProfileList
// ---------------------------------------------------------------------------
StreamProfileList::StreamProfileList(std::unique_ptr<StreamProfileListImpl> impl)
    : impl_(std::move(impl)) {}

uint32_t StreamProfileList::count() const {
  return impl_ ? static_cast<uint32_t>(impl_->profiles.size()) : 0;
}

const std::shared_ptr<StreamProfile> StreamProfileList::getProfile(uint32_t index) const {
  if (!impl_ || index >= impl_->profiles.size()) {
    obsdk::throwError("StreamProfileList::getProfile index out of range: " +
                      std::to_string(index));
  }
  return impl_->profiles[index];
}

const std::shared_ptr<VideoStreamProfile> StreamProfileList::getVideoStreamProfile(
    int width, int height, OBFormat format, int fps) const {
  if (impl_) {
    for (const auto &profile : impl_->profiles) {
      if (!profile) {
        continue;
      }
      auto video = std::dynamic_pointer_cast<VideoStreamProfile>(profile);
      if (!video) {
        continue;
      }
      if (width != 0 && static_cast<int>(video->width()) != width) {
        continue;
      }
      if (height != 0 && static_cast<int>(video->height()) != height) {
        continue;
      }
      if (format != OB_FORMAT_UNKNOWN && video->format() != format) {
        continue;
      }
      if (fps != 0 && static_cast<int>(video->fps()) != fps) {
        continue;
      }
      return video;
    }
  }
  obsdk::throwError("No video stream profile matches width=" + std::to_string(width) +
                    ", height=" + std::to_string(height) +
                    ", format=" + std::to_string(static_cast<int>(format)) +
                    ", fps=" + std::to_string(fps));
}

}  // namespace ob

// ob::Sensor / ob::SensorList implementation.
#include "ob_internal.h"

namespace ob {

struct SensorImpl {
  OBSensorType type = OB_SENSOR_UNKNOWN;
  obsdk::DeviceCorePtr core;
  std::shared_ptr<StreamProfileList> profiles;  // cached, also exposed via core
  FrameCallback frame_callback;
  bool running = false;
};

struct SensorListImpl {
  std::vector<std::shared_ptr<Sensor>> sensors;
};

// ---------------------------------------------------------------------------
// Sensor
// ---------------------------------------------------------------------------
Sensor::Sensor(std::unique_ptr<SensorImpl> impl) : impl_(std::move(impl)) {}

Sensor::~Sensor() noexcept = default;

OBSensorType Sensor::type() { return impl_ ? impl_->type : OB_SENSOR_UNKNOWN; }

const std::shared_ptr<StreamProfileList> Sensor::getStreamProfileList() {
  if (!impl_) {
    obsdk::throwError("Sensor::getStreamProfileList: invalid sensor");
  }
  if (!impl_->profiles) {
    if (!impl_->core) {
      return std::make_shared<StreamProfileList>(
          std::make_unique<obsdk::StreamProfileListImpl>());
    }
    impl_->profiles = impl_->core->profilesFor(impl_->type);
  }
  return impl_->profiles;
}

void Sensor::start(std::shared_ptr<StreamProfile> streamProfile, FrameCallback callback) {
  if (!impl_) {
    obsdk::throwError("Sensor::start: invalid sensor");
  }
  // Direct sensor start is only used for IMU streams by the ROS node, and the
  // gemini launch file never starts IMU. Video streams are started by Pipeline.
  (void)streamProfile;
  impl_->frame_callback = std::move(callback);
  impl_->running = true;
  obsdk::OBSDK_DEBUG("Sensor::start (direct) type=" << impl_->type);
}

void Sensor::stop() {
  if (impl_) {
    impl_->running = false;
    impl_->frame_callback = nullptr;
  }
}

void Sensor::switchProfile(std::shared_ptr<StreamProfile> streamProfile) {
  (void)streamProfile;
  obsdk::throwError("Sensor::switchProfile is not supported");
}

// ---------------------------------------------------------------------------
// SensorList
// ---------------------------------------------------------------------------
SensorList::SensorList(std::unique_ptr<SensorListImpl> impl) : impl_(std::move(impl)) {}

SensorList::~SensorList() noexcept = default;

uint32_t SensorList::count() {
  return impl_ ? static_cast<uint32_t>(impl_->sensors.size()) : 0;
}

OBSensorType SensorList::type(uint32_t index) {
  if (!impl_ || index >= impl_->sensors.size() || !impl_->sensors[index]) {
    obsdk::throwError("SensorList::type index out of range");
  }
  return impl_->sensors[index]->type();
}

std::shared_ptr<Sensor> SensorList::getSensor(uint32_t index) {
  if (!impl_ || index >= impl_->sensors.size() || !impl_->sensors[index]) {
    obsdk::throwError("SensorList::getSensor index out of range");
  }
  return impl_->sensors[index];
}

std::shared_ptr<Sensor> SensorList::getSensor(OBSensorType sensorType) {
  if (impl_) {
    for (const auto &sensor : impl_->sensors) {
      if (sensor && sensor->type() == sensorType) {
        return sensor;
      }
    }
  }
  obsdk::throwError("SensorList::getSensor: sensor type not present on this device");
}

}  // namespace ob

// Internal shared definitions for the in-tree libobsensor (OrbbecSDK) replacement.
// This file is not installed and is not part of the public SDK headers.
//
// NOTE: the public hpp headers forward-declare the pimpl structs (FrameImpl,
// DeviceImpl, ...) at GLOBAL namespace scope, so every *Impl below must also
// be defined at global scope.
#pragma once

#include "libobsensor/ObSensor.h"
#include "libobsensor/ObSensor.hpp"

#include <atomic>
