// ---------------------------------------------------------------------------
// Global-scope pimpl types (declared by the public headers)
// ---------------------------------------------------------------------------

// Payload shared by (possibly several) ob::Frame views of the same data.
struct FramePayload {
  OBFrameType type = OB_FRAME_UNKNOWN;
  OBFormat format = OB_FORMAT_UNKNOWN;
  uint64_t index = 0;
  uint64_t system_time_ms = 0;  // host clock, milliseconds (SDK API unit)
  uint64_t time_stamp_us = 0;   // device timestamp when available
  uint32_t width = 0;
  uint32_t height = 0;
  float value_scale = 1.0f;     // DepthFrame::getValueScale
  OBFrameType data_source = OB_FRAME_IR;
  std::shared_ptr<std::vector<uint8_t>> data;
};

struct FrameImpl {
  FramePayload payload;
  // FrameSet children (owned with correct dynamic types, see ob_frame.cpp).
  std::vector<std::shared_ptr<ob::Frame>> frames;
};

// Where a profile lives in the USB/UVC topology.
struct ProfileSource {
  int streaming_interface = -1;  // index into UvcTopology::streaming
  int format_index = 0;
  int frame_index = 0;
  uint32_t interval = 0;
};

struct StreamProfileImpl {
  OBStreamType stream_type = OB_STREAM_UNKNOWN;
  OBFormat format = OB_FORMAT_UNKNOWN;
  uint32_t width = 0;
  uint32_t height = 0;
  uint32_t fps = 0;
  OBAccelFullScaleRange accel_range = OB_ACCEL_FS_8g;
  OBAccelSampleRate accel_rate = OB_SAMPLE_RATE_200_HZ;
  OBGyroFullScaleRange gyro_range = OB_GYRO_FS_500dps;
  OBGyroSampleRate gyro_rate = OB_SAMPLE_RATE_200_HZ;
  ProfileSource source;
};

struct StreamProfileListImpl {
  std::vector<std::shared_ptr<ob::StreamProfile>> profiles;
};

struct ContextImpl;
struct DeviceImpl;
struct DeviceInfoImpl;
