struct FilterImpl;
struct ErrorImpl;

namespace obsdk {

// ---------------------------------------------------------------------------
// Logging / errors / version
// ---------------------------------------------------------------------------
void logSetSeverity(OBLogSeverity severity);
OBLogSeverity logSeverity();
void logWrite(OBLogSeverity severity, const char *file, int line, const std::string &msg);

#define OBSDK_LOG(sev, msg)                                                          \
  do {                                                                               \
    if (static_cast<int>(sev) >= static_cast<int>(obsdk::logSeverity())) {           \
      obsdk::logWrite(sev, __FILE__, __LINE__, (std::ostringstream() << msg).str()); \
    }                                                                                \
  } while (0)
#define OBSDK_DEBUG(msg) OBSDK_LOG(OB_LOG_SEVERITY_DEBUG, msg)
#define OBSDK_INFO(msg) OBSDK_LOG(OB_LOG_SEVERITY_INFO, msg)
#define OBSDK_WARN(msg) OBSDK_LOG(OB_LOG_SEVERITY_WARN, msg)
#define OBSDK_ERROR(msg) OBSDK_LOG(OB_LOG_SEVERITY_ERROR, msg)

[[noreturn]] void throwError(const std::string &message);
void throwIf(bool condition, const std::string &message);

// ---------------------------------------------------------------------------
// Device database (PID -> product identity)
// ---------------------------------------------------------------------------
enum class ProductClass {
  kUnknown,
  kGemini,  // 640x400 Y11 depth / 640x480 MJPG color / 640x400 Y10 IR
  kGemini2,
  kAstraPlus,
  kAstraMini,
  kFemto,
  kFemtoMega,
  kGenericOrbbec,
};

struct ProductInfo {
  uint16_t pid;
  const char *name;
  ProductClass klass;
};

const ProductInfo *lookupProduct(uint16_t pid);

// ---------------------------------------------------------------------------
// USB backend (raw usbfs; no libusb/libudev dependency)
// ---------------------------------------------------------------------------

struct UsbDeviceInfo {
  std::string sysfs_path;    // /sys/bus/usb/devices/... (stable location)
  std::string uid;           // stable unique id used for hotplug matching
  std::string serial;        // may be empty
  std::string manufacturer;  // may be empty
  std::string product;       // may be empty
  uint16_t vid = 0;
  uint16_t pid = 0;
  uint16_t bcd_device = 0;
  uint8_t bus_number = 0;
  uint8_t device_address = 0;
  int speed = 0;
  std::string devnode;  // /dev/bus/usb/BBB/DDD
};

std::vector<UsbDeviceInfo> enumerateUsbDevices();

class UsbConnection {
 public:
  UsbConnection() = default;
  ~UsbConnection();
  UsbConnection(const UsbConnection &) = delete;
  UsbConnection &operator=(const UsbConnection &) = delete;

  void open(const UsbDeviceInfo &info);
  void close();
  bool isOpen() const { return fd_ >= 0; }

  const std::vector<uint8_t> &configDescriptor() const { return config_desc_; }

  // Returns bytes transferred, or -1 on failure (errno set).
  int controlTransfer(uint8_t bm_request_type, uint8_t b_request, uint16_t w_value,
                      uint16_t w_index, uint8_t *data, uint16_t w_length, int timeout_ms = 1000);

  void detachKernelDriver(uint8_t interface_number);
  bool claimInterface(uint8_t interface_number);
  void releaseInterface(uint8_t interface_number);
  void setInterface(uint8_t interface_number, uint8_t alternate_setting);

  // String descriptor (index) as UTF-8, empty on failure.
  std::string getStringDescriptor(uint8_t index, int timeout_ms = 500);

  int fd() const { return fd_; }

 private:
  int fd_ = -1;
  std::vector<uint8_t> config_desc_;
};

// ---------------------------------------------------------------------------
// UVC descriptor model
// ---------------------------------------------------------------------------

struct UvcFrame {
  uint8_t frame_index = 0;
  uint32_t width = 0;
  uint32_t height = 0;
  std::vector<uint32_t> intervals;  // 100ns units
};

struct UvcFormat {
  uint8_t format_index = 0;
  OBFormat ob_format = OB_FORMAT_UNKNOWN;
  uint32_t fourcc = 0;   // for uncompressed formats
  uint8_t guid[16] = {0};
  uint8_t bits_per_pixel = 0;  // packed/vendor formats when reported
  std::vector<UvcFrame> frames;
};

struct UvcExtensionUnit {
  uint8_t unit_id = 0;
  uint8_t guid[16] = {0};
  std::string guid_str;
  std::vector<uint8_t> controls;
  uint8_t source_id = 0;
};

struct UvcTerminal {
  uint8_t terminal_id = 0;
  uint16_t type = 0;
  std::string name;  // from string descriptor, may be empty
  uint8_t source_id = 0;
};

struct UvcStreamingInterface {
  uint8_t interface_number = 0;
  uint8_t terminal_link = 0;  // bTerminalLink -> VC output terminal id
  OBStreamType stream_type = OB_STREAM_UNKNOWN;
  struct AltSetting {
    uint8_t alternate = 0;
    uint8_t endpoint_address = 0;
    uint16_t max_packet_size = 0;
    uint8_t attributes = 0;  // transfer type bits 1:0 (2 = isoc, 3 = bulk)
  };
  std::vector<AltSetting> alt_settings;
  std::vector<UvcFormat> formats;
};

struct UvcControlInterface {
  uint8_t interface_number = 0;
  uint8_t processing_unit_id = 0;
  uint8_t camera_terminal_id = 0;
  std::vector<UvcExtensionUnit> extension_units;
  // VC terminals (camera input / streaming output) with string names.
  std::vector<UvcTerminal> terminals;
};

struct UvcTopology {
  UvcControlInterface control;
  std::vector<UvcStreamingInterface> streaming;
  bool valid = false;
};

UvcTopology parseUvcTopology(const std::vector<uint8_t> &config_desc);
void resolveUvcNames(UsbConnection &conn, UvcTopology &topo);

// Maps a VS interface + format + frame + interval onto a stream type.
OBStreamType classifyStream(const UvcTopology &topo, const UvcStreamingInterface &vs,
                            const UvcFormat &format);

// ---------------------------------------------------------------------------
// Property access (UVC PU/XU controls with software cache fallback)
// ---------------------------------------------------------------------------

class PropertyStore {
 public:
  PropertyStore(std::shared_ptr<UsbConnection> conn, UvcTopology topo);
  ~PropertyStore();

  int32_t getInt(OBPropertyID id);
  void setInt(OBPropertyID id, int32_t value);
  bool getBool(OBPropertyID id);
  void setBool(OBPropertyID id, bool value);

 private:
  struct ControlRoute {
    enum Kind { kNone, kProcessingUnit, kCameraTerminal, kExtensionUnit, kSoftware };
    Kind kind = kSoftware;
    uint8_t unit_id = 0;
    uint8_t selector = 0;
    uint8_t size = 4;      // control size in bytes
    uint8_t offset = 0;    // byte offset inside the control block
    int32_t software_default = 0;
  };
  ControlRoute routeFor(OBPropertyID id) const;
  bool xferGet(const ControlRoute &route, uint8_t *buf, uint8_t len);
  bool xferSet(const ControlRoute &route, const uint8_t *buf, uint8_t len);

  std::shared_ptr<UsbConnection> conn_;
  UvcTopology topo_;
  std::map<int, int32_t> cache_;
  std::mutex mutex_;
};

// ---------------------------------------------------------------------------
// Frames
// ---------------------------------------------------------------------------
std::shared_ptr<ob::Frame> makeFrame(const RawFrame &raw);
std::shared_ptr<ob::Frame> makeFrameSet(std::vector<std::shared_ptr<ob::Frame>> children,
                                        uint64_t system_time_ms);

// Raw frame delivered by a capture backend before it becomes an ob::Frame.
struct RawFrame {
  OBFrameType type = OB_FRAME_UNKNOWN;
  OBFormat format = OB_FORMAT_UNKNOWN;
  uint32_t width = 0;
  uint32_t height = 0;
  uint64_t system_time_ms = 0;
  uint64_t time_stamp_us = 0;
  std::shared_ptr<std::vector<uint8_t>> data;
};

using RawFrameCallback = std::function<void(const RawFrame &)>;

// Unpacks/normalizes a captured frame in place (Y10/Y11/Y12 -> Y16, etc).
void normalizeRawFrame(RawFrame &raw);

// ---------------------------------------------------------------------------
// Device core
// ---------------------------------------------------------------------------

struct DeviceInfoData {
  std::string name;
  std::string uid;
  std::string serial;
  std::string firmware_version;
  std::string hardware_version;
  std::string min_sdk_version = "1.5.0";
  std::string connection_type = "USB";
  std::string usb_type = "USB3";
  std::string asic_name;
  int vid = 0;
  int pid = 0;
  uint16_t bcd_device = 0;
  OBDeviceType device_type = OB_STRUCTURED_LIGHT_MONOCULAR_CAMERA;
  std::string sysfs_path;
  std::string devnode;
};

class DeviceCore;
using DeviceCorePtr = std::shared_ptr<DeviceCore>;

// One running stream (owns the usbfs URB loop for one VS interface).
class StreamRunner {
 public:
  virtual ~StreamRunner() = default;
  virtual void start(RawFrameCallback cb) = 0;
  virtual void stop() = 0;
};

struct DeviceCore : std::enable_shared_from_this<DeviceCore> {
  DeviceInfoData info;
  ProductClass klass = ProductClass::kUnknown;

  std::mutex open_mutex;
  bool opened = false;
  std::shared_ptr<UsbConnection> conn;
  UvcTopology topo;
  std::unique_ptr<PropertyStore> properties;

  std::mutex profile_mutex;
  std::map<OBSensorType, std::shared_ptr<ob::StreamProfileList>> profile_lists;
  std::map<OBSensorType, std::shared_ptr<ob::Sensor>> sensors;
  std::vector<std::shared_ptr<ob::Sensor>> sensor_order;

  std::mutex calib_mutex;
  bool calib_loaded = false;
  std::vector<OBCameraParam> camera_params;

  std::mutex runner_mutex;
  std::map<int, std::shared_ptr<StreamRunner>> runners;  // key: streaming iface index

  void ensureOpen();
  std::shared_ptr<UsbConnection> connection();

  std::shared_ptr<ob::StreamProfileList> profilesFor(OBSensorType type);
  const std::vector<OBCameraParam> &calibrationParams();

  // Creates + starts capture runners for the enabled profiles. callbacks is
  // keyed by streaming interface index.
  void startStreams(const std::vector<std::shared_ptr<ob::StreamProfile>> &profiles,
                    const std::map<int, RawFrameCallback> &callbacks);
  void stopStreams();

  virtual ~DeviceCore() = default;
};

DeviceCorePtr createDeviceCore(const UsbDeviceInfo &usb_info);

// Creates the capture backend for one streaming interface (usb_uvc.cpp).
std::shared_ptr<StreamRunner> createUvcRunner(const DeviceCorePtr &core, int streaming_index,
                                              const ProfileSource &source);

// Calibration loading (calibration.cpp).
void loadCalibrationParams(const DeviceCorePtr &core, std::vector<OBCameraParam> &out);

}  // namespace obsdk

// ---------------------------------------------------------------------------
// pimpl payload structs
// ---------------------------------------------------------------------------

struct ContextImpl {
  std::mutex mutex;
  std::vector<obsdk::UsbDeviceInfo> devices;  // last enumeration
  std::set<std::string> uids;
  ob::Context::DeviceChangedCallback device_changed;
  bool stop = false;
  std::thread watcher;
  std::shared_ptr<ob::DeviceList> cached_list;

  // Devices created through this context are tracked so hot-unplug of an open
  // device still reports it as removed (open devices leave /sys only on
  // unplug anyway; we re-enumerate the bus each tick).
};

