  std::vector<obsdk::UsbDeviceInfo> devices;
  // Device infos are built lazily per index; reused so uid() is stable.
  std::vector<std::shared_ptr<obsdk::DeviceInfoData>> infos;
  // Reused device instances (getDevice returns the same object twice).
  std::vector<obsdk::DeviceCorePtr> cores;
};

struct DeviceImpl {
  obsdk::DeviceCorePtr core;
