// ob::DeviceInfo / DeviceList / Device / CameraParamList and DeviceCore.
#include "ob_internal.h"

#include <algorithm>
#include <cstring>

namespace obsdk {

namespace {

DeviceInfoData buildInfo(const UsbDeviceInfo &usb) {
  DeviceInfoData info;
  info.vid = usb.vid;
  info.pid = usb.pid;
  info.bcd_device = usb.bcd_device;
  info.serial = usb.serial;
  info.sysfs_path = usb.sysfs_path;
  info.devnode = usb.devnode;
  info.uid = usb.uid;
  if (!usb.product.empty()) {
    info.name = usb.product;
  } else if (const ProductInfo *product = lookupProduct(usb.pid)) {
    info.name = product->name;
  } else {
    info.name = "Orbbec Camera";
  }
  // bcdDevice conventionally carries the firmware version for these devices.
  if (usb.bcd_device != 0) {
    info.firmware_version = std::to_string((usb.bcd_device >> 8) & 0xff) + "." +
                            std::to_string((usb.bcd_device >> 4) & 0xf) + "." +
                            std::to_string(usb.bcd_device & 0xf);
  }
  info.hardware_version = "V" + std::to_string((usb.bcd_device >> 8) & 0xff) + "." +
                          std::to_string((usb.bcd_device >> 4) & 0xf);
  return info;
}

}  // namespace

DeviceCorePtr createDeviceCore(const UsbDeviceInfo &usb_info) {
  auto core = std::make_shared<DeviceCore>();
  core->info = buildInfo(usb_info);
  if (const ProductInfo *product = lookupProduct(usb_info.pid)) {
    core->klass = product->klass;
  } else {
    core->klass = ProductClass::kGenericOrbbec;
    OBSDK_WARN("USB device " << std::hex << usb_info.vid << ":" << usb_info.pid << std::dec
                             << " is not in the known Orbbec pid table; treating it as generic");
  }
  core->info.device_type =
      (core->klass == ProductClass::kGemini2 || core->klass == ProductClass::kFemtoMega)
          ? OB_TOF_CAMERA
          : OB_STRUCTURED_LIGHT_MONOCULAR_CAMERA;
  return core;
}

void DeviceCore::ensureOpen() {
  std::lock_guard<std::mutex> lock(open_mutex);
  if (opened) {
    return;
  }
  conn = std::make_shared<UsbConnection>();
  UsbDeviceInfo usb;
  usb.sysfs_path = info.sysfs_path;
  usb.devnode = info.devnode;
  usb.vid = static_cast<uint16_t>(info.vid);
  usb.pid = static_cast<uint16_t>(info.pid);
  usb.serial = info.serial;
  conn->open(usb);

  topo = parseUvcTopology(conn->configDescriptor());
  if (!topo.valid) {
    throwError("Device " + info.uid + " does not expose a valid UVC topology");
  }
  resolveUvcNames(*conn, topo);
  properties = std::make_unique<PropertyStore>(conn, topo);
  opened = true;
  OBSDK_INFO("Opened device " << info.name << " (uid=" << info.uid << ", " << info.vid << ":"
                              << info.pid << "), " << topo.streaming.size()
                              << " streaming interface(s)");
}

std::shared_ptr<UsbConnection> DeviceCore::connection() {
  ensureOpen();
  return conn;
}

std::shared_ptr<ob::StreamProfileList> DeviceCore::profilesFor(OBSensorType type) {
  {
    std::lock_guard<std::mutex> lock(profile_mutex);
    auto it = profile_lists.find(type);
    if (it != profile_lists.end()) {
      return it->second;
    }
  }
  ensureOpen();

  auto list_impl = std::make_unique<StreamProfileListImpl>();
  for (size_t vs_index = 0; vs_index < topo.streaming.size(); ++vs_index) {
    const auto &vs = topo.streaming[vs_index];
    if (vs.stream_type == OB_STREAM_UNKNOWN) {
      continue;
    }
    OBSensorType sensor_type = OB_SENSOR_UNKNOWN;
    switch (vs.stream_type) {
      case OB_STREAM_DEPTH:
        sensor_type = OB_SENSOR_DEPTH;
        break;
      case OB_STREAM_COLOR:
        sensor_type = OB_SENSOR_COLOR;
        break;
      case OB_STREAM_IR:
      case OB_STREAM_IR_LEFT:
      case OB_STREAM_IR_RIGHT:
        sensor_type = OB_SENSOR_IR;
        break;
      default:
        continue;
    }
    if (sensor_type != type) {
      continue;
    }
    for (const auto &format : vs.formats) {
      std::vector<OBFormat> offered = {format.ob_format};
      // The SDK unpacks packed depth/IR formats to Y16 by default, so expose
      // Y16 aliases for packed formats (matches the original profile lists).
      switch (format.ob_format) {
        case OB_FORMAT_Y10:
        case OB_FORMAT_Y11:
        case OB_FORMAT_Y12:
        case OB_FORMAT_Y14:
        case OB_FORMAT_RLE:
          offered.push_back(OB_FORMAT_Y16);
          break;
        default:
          break;
      }
      for (const auto &frame : format.frames) {
        if (frame.intervals.empty()) {
          continue;
        }
        for (uint32_t interval : frame.intervals) {
          uint32_t fps = interval > 0 ? static_cast<uint32_t>((10000000u + interval / 2) / interval) : 0;
          for (OBFormat offered_format : offered) {
            auto impl = std::make_unique<StreamProfileImpl>();
            impl->stream_type = vs.stream_type;
            impl->format = offered_format;
            impl->width = frame.width;
            impl->height = frame.height;
            impl->fps = fps;
            impl->source.streaming_interface = static_cast<int>(vs_index);
            impl->source.format_index = format.format_index;
            impl->source.frame_index = frame.frame_index;
            impl->source.interval = interval;
            StreamProfile base(reinterpret_cast<std::unique_ptr<StreamProfileImpl>>(nullptr));
            (void)base;  // placeholder removed below
            list_impl->profiles.push_back(
                std::make_shared<ob::VideoStreamProfile>(*(ob::StreamProfile *)nullptr));
          }
        }
      }
    }
  }

  std::lock_guard<std::mutex> lock(profile_mutex);
  auto list = std::make_shared<ob::StreamProfileList>(std::move(list_impl));
  profile_lists[type] = list;
  return list;
}

const std::vector<OBCameraParam> &DeviceCore::calibrationParams() {
  std::lock_guard<std::mutex> lock(calib_mutex);
  if (!calib_loaded) {
    ensureOpen();
    loadCalibrationParams(shared_from_this(), camera_params);
    calib_loaded = true;
  }
  return camera_params;
}

void DeviceCore::startStreams(const std::vector<std::shared_ptr<ob::StreamProfile>> &profiles,
                              const std::map<int, RawFrameCallback> &callbacks) {
  std::lock_guard<std::mutex> lock(runner_mutex);
  if (!runners.empty()) {
    throwError("DeviceCore::startStreams: streams are already running");
  }
  for (const auto &profile : profiles) {
    if (!profile) {
      continue;
    }
    auto impl = std::unique_ptr<StreamProfileImpl>(
        profile->impl_ ? new StreamProfileImpl(*profile->impl_) : nullptr);
    if (!impl) {
      continue;
    }
    int iface = impl->source.streaming_interface;
    if (iface < 0) {
      throwError("Stream profile has no source interface");
    }
    if (runners.count(iface)) {
      // Two enabled profiles sharing one VS interface cannot stream at once.
      OBSDK_WARN("Two stream profiles share streaming interface " << iface
                                                                  << "; the first one wins");
      continue;
    }
    auto cb_it = callbacks.find(iface);
    if (cb_it == callbacks.end()) {
      throwError("No frame callback registered for streaming interface " + std::to_string(iface));
    }
    auto runner = createUvcRunner(shared_from_this(), iface, impl->source);
    runner->start(cb_it->second);
    runners[iface] = runner;
  }
  if (runners.empty()) {
    throwError("DeviceCore::startStreams: no stream could be started");
  }
}

void DeviceCore::stopStreams() {
  std::map<int, std::shared_ptr<StreamRunner>> to_stop;
  {
    std::lock_guard<std::mutex> lock(runner_mutex);
    to_stop.swap(runners);
  }
  for (auto &entry : to_stop) {
    entry.second->stop();
  }
}

