std::shared_ptr<DeviceInfoImpl> infoImplFor(const std::unique_ptr<DeviceListImpl> &impl,
                                             uint32_t index) {
  if (!impl || index >= impl->devices.size()) {
    obsdk::throwError("DeviceList index out of range: " + std::to_string(index));
  }
  if (!impl->infos[index]) {
    auto info = std::make_unique<DeviceInfoImpl>();
    info->data = obsdk::DeviceInfoData();  // filled lazily below
    impl->infos[index] = std::move(info);
  }
  return impl->infos[index];
}
}  // namespace

uint32_t DeviceList::deviceCount() {
  return impl_ ? static_cast<uint32_t>(impl_->devices.size()) : 0;
}

const char *DeviceList::name(uint32_t index) {
  auto info = infoImplFor(impl_, index);
  if (info->data.name.empty()) {
    // Build info from the usb record on first access.
    const auto &usb = impl_->devices[index];
    if (!usb.product.empty()) {
      info->data.name = usb.product;
    } else if (const obsdk::ProductInfo *product = obsdk::lookupProduct(usb.pid)) {
      info->data.name = product->name;
    } else {
      info->data.name = "Orbbec Camera";
    }
    info->data.pid = usb.pid;
    info->data.vid = usb.vid;
    info->data.uid = usb.uid;
    info->data.serial = usb.serial;
    info->data.bcd_device = usb.bcd_device;
    info->data.sysfs_path = usb.sysfs_path;
    info->data.devnode = usb.devnode;
  }
  return info->data.name.c_str();
}

int DeviceList::pid(uint32_t index) {
  infoImplFor(impl_, index);
  return impl_->devices[index].pid;
}

int DeviceList::vid(uint32_t index) {
  infoImplFor(impl_, index);
  return impl_->devices[index].vid;
}

const char *DeviceList::uid(uint32_t index) {
  auto info = infoImplFor(impl_, index);
  if (info->data.uid.empty()) {
    info->data.uid = impl_->devices[index].uid;
  }
  return info->data.uid.c_str();
}

const char *DeviceList::serialNumber(uint32_t index) {
  auto info = infoImplFor(impl_, index);
  if (info->data.serial.empty()) {
    info->data.serial = impl_->devices[index].serial;
  }
  return info->data.serial.c_str();
}

std::shared_ptr<Device> DeviceList::getDevice(uint32_t index) {
  infoImplFor(impl_, index);
  if (!impl_->cores[index]) {
    impl_->cores[index] = obsdk::createDeviceCore(impl_->devices[index]);
  }
  auto device_impl = std::make_unique<DeviceImpl>();
  device_impl->core = impl_->cores[index];
  auto info_impl = std::make_unique<DeviceInfoImpl>();
  info_impl->data = device_impl->core->info;
  device_impl->device_info = std::make_shared<DeviceInfo>(std::move(info_impl));
  return std::make_shared<Device>(std::move(device_impl));
}

std::shared_ptr<Device> DeviceList::getDeviceBySN(const char *serialNumber) {
  for (uint32_t i = 0; i < deviceCount(); ++i) {
    if (std::strcmp(serialNumber(i), serialNumber ? serialNumber : "") == 0) {
      return getDevice(i);
    }
  }
  obsdk::throwError("DeviceList::getDeviceBySN: no device with the given serial number");
}

std::shared_ptr<Device> DeviceList::getDeviceByUid(const char *deviceUid) {
  for (uint32_t i = 0; i < deviceCount(); ++i) {
    if (std::strcmp(uid(i), deviceUid ? deviceUid : "") == 0) {
      return getDevice(i);
    }
  }
  obsdk::throwError("DeviceList::getDeviceByUid: no device with the given uid");
}

