std::shared_ptr<SensorList> Device::getSensorList() {
  auto core = coreOf(impl_);
  core->ensureOpen();
  if (!impl_->sensor_list) {
    std::vector<OBSensorType> types;
    for (const auto &vs : core->topo.streaming) {
      switch (vs.stream_type) {
        case OB_STREAM_DEPTH:
          types.push_back(OB_SENSOR_DEPTH);
          break;
        case OB_STREAM_COLOR:
          types.push_back(OB_SENSOR_COLOR);
          break;
        case OB_STREAM_IR:
        case OB_STREAM_IR_LEFT:
        case OB_STREAM_IR_RIGHT:
          types.push_back(OB_SENSOR_IR);
          break;
        default:
          break;
      }
    }
    std::sort(types.begin(), types.end());
    types.erase(std::unique(types.begin(), types.end()), types.end());

    auto list_impl = std::make_unique<SensorListImpl>();
    for (OBSensorType type : types) {
      if (core->sensors.count(type)) {
        list_impl->sensors.push_back(core->sensors[type]);
        continue;
      }
      auto sensor_impl = std::make_unique<SensorImpl>();
      sensor_impl->type = type;
      sensor_impl->core = core;
      sensor_impl->profiles = core->profilesFor(type);
      auto sensor = std::make_shared<Sensor>(std::move(sensor_impl));
      core->sensors[type] = sensor;
      core->sensor_order.push_back(sensor);
      list_impl->sensors.push_back(sensor);
    }
    impl_->sensor_list = std::make_shared<SensorList>(std::move(list_impl));
  }
  return impl_->sensor_list;
}

std::shared_ptr<Sensor> Device::getSensor(OBSensorType type) {
  auto list = getSensorList();
  if (list->count() == 0) {
    obsdk::throwError("Device has no sensors");
  }
  for (uint32_t i = 0; i < list->count(); ++i) {
    if (list->type(i) == type) {
      return list->getSensor(i);
    }
  }
  obsdk::throwError("Requested sensor type is not supported by this device");
}

