  return switchDepthWorkMode(workMode.name);
}

OBStatus Device::switchDepthWorkMode(const char *modeName) {
  (void)modeName;
  // Only relevant for depth-mode capable devices (Gemini2+); the gemini launch
  // file passes an empty mode and never calls this.
  return OB_STATUS_OK;
}

std::shared_ptr<OBDepthWorkModeList> Device::getDepthWorkModeList() {
  auto impl = std::make_unique<OBDepthWorkModeListImpl>();
  OBDepthWorkMode mode{};
  std::strcpy(mode.name, "DEFAULT");
  impl->modes.push_back(mode);
  return std::make_shared<OBDepthWorkModeList>(std::move(impl));
}

void Device::reboot() { obsdk::throwError("reboot is not supported"); }

OBDeviceSyncConfig Device::getSyncConfig() {
  OBDeviceSyncConfig config{};
  config.syncMode = OB_SYNC_MODE_CLOSE;
  return config;
}

void Device::setSyncConfig(const OBDeviceSyncConfig &deviceSyncConfig) {
  if (deviceSyncConfig.syncMode == OB_SYNC_MODE_CLOSE) {
    return;
  }
  // Multi-device sync wiring requires firmware support; log and continue so a
  // single camera keeps working.
  OBSDK_WARN("setSyncConfig: mode " << static_cast<int>(deviceSyncConfig.syncMode)
                                    << " is not supported by the open implementation; ignored");
}

