// ob::Context: device enumeration, hotplug watching, logging config.
#include "ob_internal.h"

#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <set>

namespace obsdk {

namespace {

// Minimal read of <LogLevel>N</LogLevel> from the SDK config xml (no xml lib).
OBLogSeverity severityFromConfig(const char *config_path) {
  if (!config_path || !*config_path) {
    return OB_LOG_SEVERITY_NONE;
  }
  std::ifstream file(config_path);
  if (!file) {
    return OB_LOG_SEVERITY_NONE;
  }
  std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
  auto start = content.find("<LogLevel>");
  if (start == std::string::npos) {
    return OB_LOG_SEVERITY_NONE;
  }
  start += std::strlen("<LogLevel>");
  auto end = content.find("</LogLevel>", start);
  if (end == std::string::npos) {
    return OB_LOG_SEVERITY_NONE;
  }
  int level = std::atoi(content.substr(start, end - start).c_str());
  if (level < 0 || level > 5) {
    return OB_LOG_SEVERITY_NONE;
  }
  return static_cast<OBLogSeverity>(level);
}

}  // namespace

std::shared_ptr<ob::DeviceList> makeDeviceList(std::vector<UsbDeviceInfo> devices) {
  auto impl = std::make_unique<DeviceListImpl>();
  impl->devices = std::move(devices);
  impl->infos.resize(impl->devices.size());
  impl->cores.resize(impl->devices.size());
  return std::make_shared<ob::DeviceList>(std::move(impl));
}

}  // namespace obsdk

namespace ob {

Context::Context(const char *configPath) : impl_(std::make_unique<ContextImpl>()) {
  logSetSeverity(obsdk::severityFromConfig(configPath));
  impl_->devices = obsdk::enumerateUsbDevices();
  for (const auto &device : impl_->devices) {
    impl_->uids.insert(device.uid);
  }
  impl_->watcher = std::thread([this]() {
    while (true) {
      {
        std::unique_lock<std::mutex> lock(impl_->mutex);
        if (impl_->stop) {
          return;
        }
      }
      std::this_thread::sleep_for(std::chrono::milliseconds(200));
      std::vector<obsdk::UsbDeviceInfo> now = obsdk::enumerateUsbDevices();

      std::vector<obsdk::UsbDeviceInfo> removed_usb;
      std::vector<obsdk::UsbDeviceInfo> added_usb;
      {
        std::unique_lock<std::mutex> lock(impl_->mutex);
        if (impl_->stop) {
          return;
        }
        std::set<std::string> now_uids;
        for (const auto &device : now) {
          now_uids.insert(device.uid);
          if (!impl_->uids.count(device.uid)) {
            added_usb.push_back(device);
          }
        }
        for (const auto &device : impl_->devices) {
          if (!now_uids.count(device.uid)) {
            removed_usb.push_back(device);
          }
        }
        impl_->devices = now;
        impl_->uids = std::move(now_uids);
      }

      if (!removed_usb.empty() || !added_usb.empty()) {
        ob::Context::DeviceChangedCallback callback;
        {
          std::unique_lock<std::mutex> lock(impl_->mutex);
          callback = impl_->device_changed;
        }
        if (callback) {
          callback(obsdk::makeDeviceList(std::move(removed_usb)),
                   obsdk::makeDeviceList(std::move(added_usb)));
        }
      }
    }
  });
}

Context::~Context() noexcept {
  {
    std::lock_guard<std::mutex> lock(impl_->mutex);
    impl_->stop = true;
  }
  if (impl_->watcher.joinable()) {
    impl_->watcher.join();
  }
}

std::shared_ptr<DeviceList> Context::queryDeviceList() {
  std::vector<obsdk::UsbDeviceInfo> devices = obsdk::enumerateUsbDevices();
  std::lock_guard<std::mutex> lock(impl_->mutex);
  impl_->devices = devices;
  impl_->uids.clear();
  for (const auto &device : devices) {
    impl_->uids.insert(device.uid);
  }
  return obsdk::makeDeviceList(devices);
}

