#include <algorithm>

namespace {

constexpr uint64_t kSyncWindowMs = 100;      // max timestamp spread inside a set
constexpr uint64_t kPartialSetDeadlineMs = 60;  // emit without late streams after this

uint64_t nowMs() {
  return static_cast<uint64_t>(
      std::chrono::duration_cast<std::chrono::milliseconds>(
          std::chrono::steady_clock::now().time_since_epoch())
          .count());
}

}  // namespace

