void Config::disableStream(OBStreamType streamType) {
  impl_->enabled.erase(std::remove_if(impl_->enabled.begin(), impl_->enabled.end(),
                                      [streamType](const std::shared_ptr<StreamProfile> &profile) {
                                        return profile && profile->type() == streamType;
                                      }),
                       impl_->enabled.end());
}

