// Pipeline
// ---------------------------------------------------------------------------
Pipeline::Pipeline() {
  impl_ = std::make_unique<PipelineImpl>();
  auto devices = obsdk::enumerateUsbDevices();
  if (devices.empty()) {
    obsdk::throwError("Pipeline(): no Orbbec device connected");
  }
  auto core = obsdk::createDeviceCore(devices.front());
  auto device_impl = std::make_unique<DeviceImpl>();
  device_impl->core = core;
  auto info_impl = std::make_unique<DeviceInfoImpl>();
  info_impl->data = core->info;
  device_impl->device_info = std::make_shared<DeviceInfo>(std::move(info_impl));
  impl_->core = core;
  impl_->device = std::make_shared<Device>(std::move(device_impl));
}

Pipeline::Pipeline(std::shared_ptr<Device> device) : impl_(std::make_unique<PipelineImpl>()) {
  if (!device || !device->impl_ || !device->impl_->core) {
    obsdk::throwError("Pipeline(device): invalid device");
  }
  impl_->device = device;
  impl_->core = device->impl_->core;
}

Pipeline::Pipeline(const char *) {
  obsdk::throwError("Pipeline(filename): playback is not supported");
}

Pipeline::~Pipeline() noexcept {
  try {
    stop();
  } catch (...) {
  }
}

void Pipeline::start(std::shared_ptr<Config> config) {
  start(config, nullptr);
}

void Pipeline::start(std::shared_ptr<Config> config, FrameSetCallback callback) {
  if (!config || !config->impl_) {
    obsdk::throwError("Pipeline::start: invalid config");
  }
  if (!impl_ || !impl_->core) {
    obsdk::throwError("Pipeline::start: no device bound to this pipeline");
  }
  std::lock_guard<std::mutex> lock(impl_->mutex);
  if (impl_->running) {
    obsdk::throwError("Pipeline::start: pipeline is already running");
  }
  if (config->impl_->enabled.empty() && !config->impl_->enable_all) {
    obsdk::throwError("Pipeline::start: no stream enabled in config");
  }

  std::vector<std::shared_ptr<StreamProfile>> profiles = config->impl_->enabled;
  if (config->impl_->enable_all) {
    profiles.clear();
    for (const auto &sensor : impl_->core->sensor_order) {
      auto list = sensor->getStreamProfileList();
      for (uint32_t i = 0; i < list->count(); ++i) {
        profiles.push_back(list->getProfile(i));
      }
    }
  }

  impl_->config = config->impl_;
  impl_->callback = std::move(callback);
  impl_->align_mode = config->impl_->align_mode;
  impl_->queues.clear();
  for (const auto &profile : profiles) {
    impl_->queues[static_cast<int>(profile->type())].clear();
  }

  // Per-streaming-interface callback -> synchronization queues.
  std::map<int, obsdk::RawFrameCallback> callbacks;
  for (const auto &profile : profiles) {
    obsdk::ProfileSource source = impl_->core->sourceFor(profile);
    int iface = source.streaming_interface;
    if (callbacks.count(iface)) {
      continue;  // shared interface handled by startStreams warning
    }
    OBStreamType stream_type = profile->type();
    auto self = impl_.get();
    callbacks[iface] = [self, stream_type](const obsdk::RawFrame &raw) {
      obsdk::RawFrame normalized = raw;
      obsdk::normalizeRawFrame(normalized);
      {
        std::lock_guard<std::mutex> queue_lock(self->mutex);
        auto it = self->queues.find(static_cast<int>(stream_type));
        if (it == self->queues.end()) {
          return;
        }
        auto &queue = it->second;
        queue.push_back(std::move(normalized));
        while (queue.size() > 4) {
          queue.pop_front();  // drop frames nobody consumed (slow subscriber)
        }
      }
      self->cv.notify_all();
    };
  }

  try {
    impl_->core->startStreams(profiles, callbacks);
  } catch (...) {
    impl_->running = false;
    throw;
  }

  impl_->running = true;
  impl_->sync_thread = std::thread([this]() { syncLoop(); });
  OBSDK_INFO("Pipeline started with " << profiles.size() << " stream(s)");
}

namespace {

// Picks one frame per stream type: prefers sets whose timestamps agree, drops
// stale frames so one slow/dead stream cannot stall the others forever.
bool assembleFrameSet(PipelineImpl *impl, std::vector<obsdk::RawFrame> &out) {
  // all queues must exist for enabled streams; at least one queue must hold a frame
  bool any = false;
  for (const auto &entry : impl->queues) {
    if (!entry.second.empty()) {
      any = true;
      break;
    }
  }
  if (!any) {
    return false;
  }

  // Wait until every non-empty queue is ready, or the oldest queued frame
  // exceeded the partial-set deadline.
  uint64_t oldest = UINT64_MAX;
  for (const auto &entry : impl->queues) {
    if (!entry.second.empty()) {
      oldest = std::min(oldest, entry.second.front().system_time_ms);
    }
  }
  bool all_ready = true;
  for (const auto &entry : impl->queues) {
    if (entry.second.empty()) {
      all_ready = false;
      break;
    }
  }
  if (!all_ready && nowMs() - oldest < kPartialSetDeadlineMs) {
    return false;
  }

  out.clear();
  uint64_t reference = 0;
  bool have_reference = false;
  for (auto &entry : impl->queues) {
    if (entry.second.empty()) {
      continue;
    }
    obsdk::RawFrame frame = std::move(entry.second.front());
    entry.second.pop_front();
    if (!have_reference) {
      reference = frame.system_time_ms;
      have_reference = true;
      out.push_back(std::move(frame));
      continue;
    }
    // Frames too old relative to the reference are discarded (not emitted).
    if (frame.system_time_ms + kSyncWindowMs < reference) {
      continue;
    }
    out.push_back(std::move(frame));
  }

  // Drop the remaining frames that are too old w.r.t. the emitted reference.
  for (auto &entry : impl->queues) {
    while (!entry.second.empty() &&
           entry.second.front().system_time_ms + kSyncWindowMs < reference) {
      entry.second.pop_front();
    }
  }
  return !out.empty();
}

}  // namespace

void Pipeline::syncLoop() {
  std::unique_lock<std::mutex> lock(impl_->mutex);
  while (true) {
    impl_->cv.wait(lock, [this]() { return !impl_->running || pendingWork(impl_.get()); });
    if (!impl_->running) {
      return;
    }
    std::vector<obsdk::RawFrame> frames;
    while (assembleFrameSet(impl_.get(), frames)) {
      std::vector<std::shared_ptr<Frame>> children;
      uint64_t stamp = frames.empty() ? nowMs() : frames.front().system_time_ms;
      for (auto &raw : frames) {
        children.push_back(obsdk::makeFrame(raw));
      }
      auto frame_set = obsdk::makeFrameSet(std::move(children), stamp);
      auto callback = impl_->callback;
      lock.unlock();
      if (callback) {
        try {
          callback(std::static_pointer_cast<FrameSet>(frame_set));
        } catch (const std::exception &e) {
          obsdk::OBSDK_ERROR("Pipeline frame callback threw: " << e.what());
        } catch (...) {
          obsdk::OBSDK_ERROR("Pipeline frame callback threw an unknown exception");
        }
      }
      lock.lock();
      frames.clear();
    }
  }
}

bool Pipeline::pendingWork(PipelineImpl *impl) {
  for (const auto &entry : impl->queues) {
    if (!entry.second.empty()) {
      return true;
    }
  }
  return false;
}

void Pipeline::stop() {
  if (!impl_) {
    return;
  }
  std::thread sync;
  {
    std::lock_guard<std::mutex> lock(impl_->mutex);
    if (!impl_->running) {
      return;
    }
    impl_->running = false;
    sync = std::move(impl_->sync_thread);
  }
  impl_->cv.notify_all();
  if (sync.joinable()) {
    sync.join();
  }
  if (impl_->core) {
    impl_->core->stopStreams();
  }
  std::lock_guard<std::mutex> lock(impl_->mutex);
  impl_->queues.clear();
  OBSDK_INFO("Pipeline stopped");
}

