}  // namespace obsdk

// Pixel format helpers, pure C++ implementation.
#include "formats.h"

#include <algorithm>
#include <cstring>
#include <queue>

namespace obsdk {

namespace {

inline void yuvToRgb(int y, int u, int v, uint8_t &r, uint8_t &g, uint8_t &b) {
  const int c = std::max(0, y - 16);
  const int d = u - 128;
  const int e = v - 128;
  int rr = (298 * c + 409 * e + 128) >> 8;
  int gg = (298 * c - 100 * d - 208 * e + 128) >> 8;
  int bb = (298 * c + 516 * d + 128) >> 8;
  r = static_cast<uint8_t>(rr < 0 ? 0 : (rr > 255 ? 255 : rr));
  g = static_cast<uint8_t>(gg < 0 ? 0 : (gg > 255 ? 255 : gg));
  b = static_cast<uint8_t>(bb < 0 ? 0 : (bb > 255 ? 255 : bb));
}

}  // namespace

bool yuyvToRgb888(const uint8_t *src, size_t src_size, uint32_t width, uint32_t height,
                  std::vector<uint8_t> &rgb) {
  if (!src || width == 0 || height == 0 || src_size < static_cast<size_t>(width) * height * 2) {
    return false;
  }
  rgb.resize(static_cast<size_t>(width) * height * 3);
  const uint8_t *row_in = src;
  uint8_t *row_out = rgb.data();
  for (uint32_t y = 0; y < height; ++y) {
    for (uint32_t x = 0; x + 1 < width; x += 2) {
      int y0 = row_in[x * 2 + 0];
      int u = row_in[x * 2 + 1];
      int y1 = row_in[x * 2 + 2];
      int v = row_in[x * 2 + 3];
      yuvToRgb(y0, u, v, row_out[x * 3 + 0], row_out[x * 3 + 1], row_out[x * 3 + 2]);
      yuvToRgb(y1, u, v, row_out[(x + 1) * 3 + 0], row_out[(x + 1) * 3 + 1],
               row_out[(x + 1) * 3 + 2]);
    }
    if (width & 1u) {
      // odd width: last pixel without a pair
      uint32_t x = width - 1;
      int y0 = row_in[x * 2 + 0];
      int u = row_in[x * 2 + 1];
      int v = row_in[x * 2 + 3];
      yuvToRgb(y0, u, v, row_out[x * 3 + 0], row_out[x * 3 + 1], row_out[x * 3 + 2]);
    }
    row_in += width * 2;
    row_out += width * 3;
  }
  return true;
}

bool uyvyToRgb888(const uint8_t *src, size_t src_size, uint32_t width, uint32_t height,
                  std::vector<uint8_t> &rgb) {
  if (!src || width == 0 || height == 0 || src_size < static_cast<size_t>(width) * height * 2) {
    return false;
  }
  rgb.resize(static_cast<size_t>(width) * height * 3);
  const uint8_t *row_in = src;
  uint8_t *row_out = rgb.data();
  for (uint32_t y = 0; y < height; ++y) {
    for (uint32_t x = 0; x + 1 < width; x += 2) {
      int u = row_in[x * 2 + 0];
      int y0 = row_in[x * 2 + 1];
      int v = row_in[x * 2 + 2];
      int y1 = row_in[x * 2 + 3];
      yuvToRgb(y0, u, v, row_out[x * 3 + 0], row_out[x * 3 + 1], row_out[x * 3 + 2]);
      yuvToRgb(y1, u, v, row_out[(x + 1) * 3 + 0], row_out[(x + 1) * 3 + 1],
               row_out[(x + 1) * 3 + 2]);
    }
    row_in += width * 2;
    row_out += width * 3;
  }
  return true;
}

bool i420ToRgb888(const uint8_t *src, size_t src_size, uint32_t width, uint32_t height,
                  std::vector<uint8_t> &rgb) {
  const size_t y_size = static_cast<size_t>(width) * height;
  const size_t c_size = ((width + 1) / 2) * ((height + 1) / 2);
  if (!src || src_size < y_size + 2 * c_size) {
    return false;
  }
  rgb.resize(y_size * 3);
  const uint8_t *u_plane = src + y_size;
  const uint8_t *v_plane = u_plane + c_size;
  const uint32_t cw = (width + 1) / 2;
  for (uint32_t y = 0; y < height; ++y) {
    for (uint32_t x = 0; x < width; ++x) {
      int yv = src[y * width + x];
      int ci = (y / 2) * cw + (x / 2);
      yuvToRgb(yv, u_plane[ci], v_plane[ci], rgb[(y * width + x) * 3 + 0],
               rgb[(y * width + x) * 3 + 1], rgb[(y * width + x) * 3 + 2]);
    }
  }
  return true;
}

namespace {
bool semiPlanarToRgb888(const uint8_t *src, size_t src_size, uint32_t width, uint32_t height,
                        bool uv_swapped, std::vector<uint8_t> &rgb) {
  const size_t y_size = static_cast<size_t>(width) * height;
  const size_t c_size = ((width + 1) / 2) * ((height + 1) / 2) * 2;
  if (!src || src_size < y_size + c_size) {
    return false;
  }
  rgb.resize(y_size * 3);
  const uint8_t *uv = src + y_size;
  const uint32_t cw = (width + 1) / 2;
  for (uint32_t y = 0; y < height; ++y) {
    for (uint32_t x = 0; x < width; ++x) {
      int yv = src[y * width + x];
      size_t ci = ((y / 2) * cw + (x / 2)) * 2;
      int u = uv[uv_swapped ? ci + 1 : ci];
      int v = uv[uv_swapped ? ci : ci + 1];
      yuvToRgb(yv, u, v, rgb[(y * width + x) * 3 + 0], rgb[(y * width + x) * 3 + 1],
               rgb[(y * width + x) * 3 + 2]);
    }
  }
  return true;
}
}  // namespace

bool nv12ToRgb888(const uint8_t *src, size_t src_size, uint32_t width, uint32_t height,
                  std::vector<uint8_t> &rgb) {
  return semiPlanarToRgb888(src, src_size, width, height, false, rgb);
}

bool nv21ToRgb888(const uint8_t *src, size_t src_size, uint32_t width, uint32_t height,
                  std::vector<uint8_t> &rgb) {
  return semiPlanarToRgb888(src, src_size, width, height, true, rgb);
}

void unpackPackedToY16(const uint8_t *src, size_t src_bytes, uint16_t *dst, size_t pixels,
                       int bits) {
  if (!src || !dst || bits < 1 || bits > 16) {
    return;
  }
  if (bits == 16) {
    std::memcpy(dst, src, pixels * 2);
    return;
  }
  if (bits == 8) {
    for (size_t i = 0; i < pixels && i < src_bytes; ++i) {
      dst[i] = src[i];
    }
    return;
  }
  uint64_t accumulator = 0;
  int acc_bits = 0;
  size_t out = 0;
  size_t byte_index = 0;
  const uint64_t mask = (1ull << bits) - 1;
  while (out < pixels) {
    while (acc_bits < bits && byte_index < src_bytes) {
      accumulator |= static_cast<uint64_t>(src[byte_index++]) << acc_bits;
      acc_bits += 8;
    }
    if (acc_bits < bits) {
      break;  // truncated input
    }
    dst[out++] = static_cast<uint16_t>(accumulator & mask);
    accumulator >>= bits;
    acc_bits -= bits;
  }
}

void depthSpeckleFilter(uint16_t *img, int width, int height, int max_diff,
                        int max_speckle_size) {
  if (!img || width <= 0 || height <= 0 || max_speckle_size <= 0) {
    return;
  }
  const int total = width * height;
  std::vector<uint8_t> visited(total, 0);
  std::vector<int> stack;
  stack.reserve(64);
  std::vector<int> component;
  component.reserve(static_cast<size_t>(max_speckle_size) + 1);

  for (int start = 0; start < total; ++start) {
    if (visited[start] || img[start] == 0) {
      continue;
    }
    visited[start] = 1;
    stack.clear();
    stack.push_back(start);
    component.clear();
    while (!stack.empty()) {
      int idx = stack.back();
      stack.pop_back();
      component.push_back(idx);
      int cx = idx % width;
      int cy = idx / width;
      const int neighbours[4] = {cx > 0 ? idx - 1 : idx, cx + 1 < width ? idx + 1 : idx,
                                 cy > 0 ? idx - width : idx, cy + 1 < height ? idx + width : idx};
      for (int n : neighbours) {
        if (visited[n]) {
          continue;
        }
        int diff = img[n] > img[idx] ? img[n] - img[idx] : img[idx] - img[n];
        if (img[n] != 0 && diff <= max_diff) {
          visited[n] = 1;
          stack.push_back(n);
        }
      }
    }
    if (component.size() <= static_cast<size_t>(max_speckle_size)) {
      for (int idx : component) {
        img[idx] = 0;
      }
    }
  }
}

namespace {

// Backprojects with the given intrinsics; applies the OpenCV-style distortion
// model when projecting into the target camera.
inline void projectPoint(float x, float y, float z, const OBCameraIntrinsic &intr,
                         const OBCameraDistortion &dist, float &u, float &v) {
  float xn = x / z;
  float yn = y / z;
  if (dist.k1 != 0.f || dist.k2 != 0.f || dist.k3 != 0.f || dist.k4 != 0.f || dist.k5 != 0.f ||
      dist.k6 != 0.f || dist.p1 != 0.f || dist.p2 != 0.f) {
    const float r2 = xn * xn + yn * yn;
    const float r4 = r2 * r2;
    const float r6 = r4 * r2;
    const float radial =
        (1.f + dist.k1 * r2 + dist.k2 * r4 + dist.k3 * r6) /
        (1.f + dist.k4 * r2 + dist.k5 * r4 + dist.k6 * r6);
    const float dx = 2.f * dist.p1 * xn * yn + dist.p2 * (r2 + 2.f * xn * xn);
    const float dy = dist.p1 * (r2 + 2.f * yn * yn) + 2.f * dist.p2 * xn * yn;
    xn = xn * radial + dx;
    yn = yn * radial + dy;
  }
  u = intr.fx * xn + intr.cx;
  v = intr.fy * yn + intr.cy;
}

}  // namespace

void alignDepthToColor(const uint16_t *depth, uint32_t depth_width, uint32_t depth_height,
                       const OBCameraParam &param, std::vector<uint16_t> &aligned,
                       uint32_t &out_width, uint32_t &out_height) {
  const auto &d_intr = param.depthIntrinsic;
  const auto &c_intr = param.rgbIntrinsic;
  out_width = static_cast<uint32_t>(c_intr.width);
  out_height = static_cast<uint32_t>(c_intr.height);
  if (out_width == 0 || out_height == 0) {
    out_width = 640;
    out_height = 480;
  }
  aligned.assign(static_cast<size_t>(out_width) * out_height, 0);
  if (!depth || d_intr.fx == 0.f || c_intr.fx == 0.f) {
    return;
  }
  const float *rot = param.transform.rot;
  const float *trans = param.transform.trans;
  for (uint32_t v = 0; v < depth_height; ++v) {
    for (uint32_t u = 0; u < depth_width; ++u) {
      uint16_t d = depth[v * depth_width + u];
      if (d == 0) {
        continue;
      }
      float x = (static_cast<float>(u) - d_intr.cx) / d_intr.fx * d;
      float y = (static_cast<float>(v) - d_intr.cy) / d_intr.fy * d;
      float z = static_cast<float>(d);
      // depth -> color extrinsic
      float xc = rot[0] * x + rot[1] * y + rot[2] * z + trans[0];
      float yc = rot[3] * x + rot[4] * y + rot[5] * z + trans[1];
      float zc = rot[6] * x + rot[7] * y + rot[8] * z + trans[2];
      if (zc <= 0.f) {
        continue;
      }
      float uu = 0.f, vv = 0.f;
      projectPoint(xc, yc, zc, c_intr, param.rgbDistortion, uu, vv);
      int pu = static_cast<int>(uu + 0.5f);
      int pv = static_cast<int>(vv + 0.5f);
      if (pu < 0 || pv < 0 || pu >= static_cast<int>(out_width) ||
          pv >= static_cast<int>(out_height)) {
        continue;
      }
      uint16_t &slot = aligned[pv * out_width + pu];
      if (slot == 0 || zc < static_cast<float>(slot)) {
        slot = static_cast<uint16_t>(zc + 0.5f);
      }
    }
  }
}

}  // namespace obsdk

