// MJPG decoding via OpenCV (already a dependency of this ROS package).
#include "formats.h"

#include <opencv2/imgcodecs.hpp>
#include <opencv2/imgproc.hpp>

namespace obsdk {

bool mjpegToRgb888(const uint8_t *src, size_t src_size, std::vector<uint8_t> &rgb,
                   uint32_t &width, uint32_t &height) {
  if (!src || src_size < 4) {
    return false;
  }
  try {
    cv::Mat encoded(1, static_cast<int>(src_size), CV_8UC1,
                    const_cast<uint8_t *>(src));
    cv::Mat bgr = cv::imdecode(encoded, cv::IMREAD_COLOR);
    if (bgr.empty() || bgr.type() != CV_8UC3) {
      return false;
    }
    cv::Mat rgb_mat;
    cv::cvtColor(bgr, rgb_mat, cv::COLOR_BGR2RGB);
    width = static_cast<uint32_t>(rgb_mat.cols);
    height = static_cast<uint32_t>(rgb_mat.rows);
    rgb.resize(static_cast<size_t>(width) * height * 3);
    if (!rgb_mat.isContinuous()) {
      rgb_mat = rgb_mat.clone();
    }
    std::memcpy(rgb.data(), rgb_mat.data, rgb.size());
    return true;
  } catch (const cv::Exception &e) {
    (void)e;
    return false;
  }
}

