std::shared_ptr<Frame> makeColorFrameFromRgb(const FramePayload &source,
                                             std::vector<uint8_t> &&rgb, uint32_t width,
                                             uint32_t height) {
  auto impl = std::make_unique<FrameImpl>();
  impl->payload.type = OB_FRAME_COLOR;
  impl->payload.format = OB_FORMAT_RGB888;
  impl->payload.width = width;
  impl->payload.height = height;
  impl->payload.index = source.index;
  impl->payload.system_time_ms = source.system_time_ms;
  impl->payload.time_stamp_us = source.time_stamp_us;
  impl->payload.data = std::make_shared<std::vector<uint8_t>>(std::move(rgb));
  Frame base(std::move(impl));
  return std::make_shared<ColorFrame>(base);
}

std::shared_ptr<Frame> convertColorFrame(FilterImpl *state, const FramePayload &source,
                                         const std::shared_ptr<std::vector<uint8_t>> &data) {
  const uint8_t *src = data->data();
  const size_t src_size = data->size();
  std::vector<uint8_t> rgb;
  uint32_t width = source.width;
  uint32_t height = source.height;

  switch (state->convert_format) {
    case FORMAT_MJPG_TO_RGB888:
      if (!obsdk::mjpegToRgb888(src, src_size, rgb, width, height)) {
        return nullptr;
      }
      break;
    case FORMAT_YUYV_TO_RGB888:
      if (!obsdk::yuyvToRgb888(src, src_size, width, height, rgb)) {
        return nullptr;
      }
      break;
    case FORMAT_UYVY_TO_RGB888:
      if (!obsdk::uyvyToRgb888(src, src_size, width, height, rgb)) {
        return nullptr;
      }
      break;
    case FORMAT_I420_TO_RGB888:
      if (!obsdk::i420ToRgb888(src, src_size, width, height, rgb)) {
        return nullptr;
      }
      break;
    case FORMAT_NV12_TO_RGB888:
      if (!obsdk::nv12ToRgb888(src, src_size, width, height, rgb)) {
        return nullptr;
      }
      break;
    case FORMAT_NV21_TO_RGB888:
      if (!obsdk::nv21ToRgb888(src, src_size, width, height, rgb)) {
        return nullptr;
      }
      break;
    default:
      obsdk::throwError("FormatConvertFilter: unsupported conversion type " +
                        std::to_string(static_cast<int>(state->convert_format)));
  }
  return makeColorFrameFromRgb(source, std::move(rgb), width, height);
}

