// Generates OBPoint / OBColorPoint cloud from a depth frame (and optionally a
// color frame for RGB points). Coordinates stay in raw depth units: the node
// multiplies by DepthFrame::getValueScale() later.
std::shared_ptr<Frame> generatePointCloud(FilterImpl *state, std::shared_ptr<DepthFrame> depth,
                                          std::shared_ptr<Frame> color_frame) {
  if (!depth || !depth->data() || depth->width() == 0 || depth->height() == 0) {
    return nullptr;
  }
  const uint32_t width = depth->width();
  const uint32_t height = depth->height();
  const auto *depth_data = static_cast<const uint16_t *>(depth->data());

  const OBCameraIntrinsic &intr = state->frame_align_state
                                       ? state->camera_param.rgbIntrinsic
                                       : state->camera_param.depthIntrinsic;
  if (intr.fx == 0.f || intr.fy == 0.f) {
    obsdk::throwError("PointCloudFilter: camera intrinsic parameters are not set");
  }

  // Optional color source for RGB point clouds.
  const uint8_t *color_rgb = nullptr;
  uint32_t color_width = 0;
  uint32_t color_height = 0;
  std::shared_ptr<std::vector<uint8_t>> decoded;
  if (state->point_format == OB_FORMAT_RGB_POINT && color_frame) {
    auto color_payload =
        std::dynamic_pointer_cast<FrameImpl>(nullptr);  // placeholder, see below
    (void)color_payload;
    // color_frame carries its impl; re-decode when MJPG, otherwise use RGB888.
    if (color_frame->format() == OB_FORMAT_MJPG) {
      decoded = std::make_shared<std::vector<uint8_t>>();
      uint32_t w = color_frame->as<VideoFrame>()->width();
      uint32_t h = color_frame->as<VideoFrame>()->height();
      if (!obsdk::mjpegToRgb888(static_cast<const uint8_t *>(color_frame->data()),
                                color_frame->dataSize(), *decoded, w, h)) {
        decoded.reset();
      } else {
        color_rgb = decoded->data();
        color_width = w;
        color_height = h;
      }
    } else if (color_frame->format() == OB_FORMAT_RGB888) {
      color_rgb = static_cast<const uint8_t *>(color_frame->data());
      color_width = color_frame->as<VideoFrame>()->width();
      color_height = color_frame->as<VideoFrame>()->height();
    }
  }

  const bool with_color = color_rgb != nullptr;
  std::vector<uint8_t> points;
  if (with_color) {
    points.resize(static_cast<size_t>(width) * height * sizeof(OBColorPoint));
  } else {
    points.resize(static_cast<size_t>(width) * height * sizeof(OBPoint));
  }
  const auto &c_intr = state->camera_param.rgbIntrinsic;
  const auto &c_dist = state->camera_param.rgbDistortion;
  const float *rot = state->camera_param.transform.rot;
  const float *trans = state->camera_param.transform.trans;
  const float scale = state->position_scale;

  auto *out_rgb = with_color ? reinterpret_cast<OBColorPoint *>(points.data()) : nullptr;
  auto *out_xyz = with_color ? nullptr : reinterpret_cast<OBPoint *>(points.data());

  for (uint32_t v = 0; v < height; ++v) {
    for (uint32_t u = 0; u < width; ++u) {
      float z = static_cast<float>(depth_data[v * width + u]);
      const size_t index = v * width + u;
      if (z <= 0.f) {
        if (with_color) {
          out_rgb[index] = OBColorPoint{0.f, 0.f, 0.f, 0.f, 0.f, 0.f};
        } else {
          out_xyz[index] = OBPoint{0.f, 0.f, 0.f};
        }
        continue;
      }
      float x = (static_cast<float>(u) - intr.cx) / intr.fx * z;
      float y = (static_cast<float>(v) - intr.cy) / intr.fy * z;
      x *= scale;
      y *= scale;
      z *= scale;
      if (!with_color) {
        out_xyz[index] = OBPoint{x, y, z};
        continue;
      }
      uint8_t r = 0, g = 0, b = 0;
      if (!state->frame_align_state && c_intr.fx != 0.f) {
        // project into color camera
        float xc = rot[0] * x + rot[1] * y + rot[2] * z + trans[0];
        float yc = rot[3] * x + rot[4] * y + rot[5] * z + trans[1];
        float zc = rot[6] * x + rot[7] * y + rot[8] * z + trans[2];
        if (zc > 0.f) {
          float xn = xc / zc;
          float yn = yc / zc;
          if (c_dist.k1 != 0.f || c_dist.k2 != 0.f || c_dist.k3 != 0.f || c_dist.k4 != 0.f ||
              c_dist.k5 != 0.f || c_dist.k6 != 0.f || c_dist.p1 != 0.f || c_dist.p2 != 0.f) {
            const float r2 = xn * xn + yn * yn;
            const float r4 = r2 * r2;
            const float r6 = r4 * r2;
            const float radial =
                (1.f + c_dist.k1 * r2 + c_dist.k2 * r4 + c_dist.k3 * r6) /
                (1.f + c_dist.k4 * r2 + c_dist.k5 * r4 + c_dist.k6 * r6);
            const float dx = 2.f * c_dist.p1 * xn * yn + c_dist.p2 * (r2 + 2.f * xn * xn);
            const float dy = c_dist.p1 * (r2 + 2.f * yn * yn) + 2.f * c_dist.p2 * xn * yn;
            xn = xn * radial + dx;
            yn = yn * radial + dy;
          }
          int pu = static_cast<int>(c_intr.fx * xn + c_intr.cx + 0.5f);
          int pv = static_cast<int>(c_intr.fy * yn + c_intr.cy + 0.5f);
          if (pu >= 0 && pv >= 0 && pu < static_cast<int>(color_width) &&
              pv < static_cast<int>(color_height)) {
            const uint8_t *pixel = color_rgb + (static_cast<size_t>(pv) * color_width + pu) * 3;
            r = pixel[0];
            g = pixel[1];
            b = pixel[2];
          }
        }
      } else if (c_intr.fx != 0.f) {
        // aligned: depth already in color viewpoint, sample by depth pixel
