std::shared_ptr<Frame> Filter::process(std::shared_ptr<Frame> frame) {
  if (!frame || !impl_) {
    return frame;
  }
  if (impl_->kind == FilterImpl::kFormatConvert) {
    if (frame->type() != OB_FRAME_COLOR || !frame->impl_ || !frame->impl_->payload.data) {
      return nullptr;
    }
    if (frame->format() == OB_FORMAT_RGB888) {
      return frame;
    }
    return convertColorFrame(impl_.get(), frame->impl_->payload, frame->impl_->payload.data);
  }
  if (impl_->kind == FilterImpl::kPointCloud) {
    std::shared_ptr<DepthFrame> depth;
    std::shared_ptr<Frame> color;
    if (frame->type() == OB_FRAME_SET) {
      auto frame_set = std::static_pointer_cast<FrameSet>(frame);
      depth = frame_set->depthFrame();
      color = frame_set->colorFrame();
    } else if (frame->type() == OB_FRAME_DEPTH) {
      depth = std::static_pointer_cast<DepthFrame>(frame);
    } else {
      obsdk::throwError("PointCloudFilter: input must be a FrameSet or a DepthFrame");
    }
    return generatePointCloud(impl_.get(), depth, color);
  }
  return frame;
}

