// Property access: standard UVC PU/CT controls + software cache fallback.
//
// The PU/CT control-selector table was recovered from
// pal::ObUvcDevice::obOptionToCtrlSelector in libOrbbecSDK.so.1.5.7; values
// travel as 4-byte UVC GET_CUR/SET_CUR transfers (bmRequestType 0xA1/0x21,
// wValue = selector<<8, wIndex = (unit<<8)|vcInterface).
#include "ob_internal.h"

#include <cstring>

namespace obsdk {

std::atomic<bool> g_soft_filter_enabled{true};
std::atomic<int> g_soft_filter_max_diff{40};
std::atomic<int> g_soft_filter_speckle_size{100};

namespace {

using Route = PropertyStore::ControlRoute;  // alias only for readability below

struct PropertyRouteEntry {
  OBPropertyID id;
  bool use_camera_terminal;
  uint8_t selector;
  PropertyStore::ControlRoute::BoolEncoding bool_encoding;
  int32_t software_default;
};

// clang-format off
const PropertyRouteEntry kUvcRoutes[] = {
    {OB_PROP_COLOR_AUTO_WHITE_BALANCE_BOOL, false, 11, PropertyStore::ControlRoute::kUvcAutoMode, 0},
    {OB_PROP_COLOR_WHITE_BALANCE_INT,       false, 10, PropertyStore::ControlRoute::kZeroOne, 4000},
    {OB_PROP_COLOR_BRIGHTNESS_INT,          false,  2, PropertyStore::ControlRoute::kZeroOne, 0},
    {OB_PROP_COLOR_SHARPNESS_INT,           false,  8, PropertyStore::ControlRoute::kZeroOne, 0},
    {OB_PROP_COLOR_SATURATION_INT,          false,  7, PropertyStore::ControlRoute::kZeroOne, 64},
    {OB_PROP_COLOR_CONTRAST_INT,            false,  3, PropertyStore::ControlRoute::kZeroOne, 64},
    {OB_PROP_COLOR_GAMMA_INT,               false,  9, PropertyStore::ControlRoute::kZeroOne, 64},
    {OB_PROP_COLOR_BACKLIGHT_COMPENSATION_INT, false, 1, PropertyStore::ControlRoute::kZeroOne, 0},
    {OB_PROP_COLOR_HUE_INT,                 false,  6, PropertyStore::ControlRoute::kZeroOne, 0},
    {OB_PROP_COLOR_POWER_LINE_FREQUENCY_INT,false,  5, PropertyStore::ControlRoute::kZeroOne, 2},
    {OB_PROP_COLOR_GAIN_INT,                false,  4, PropertyStore::ControlRoute::kZeroOne, 0},
    {OB_PROP_COLOR_AUTO_EXPOSURE_BOOL,      true,   2, PropertyStore::ControlRoute::kUvcAutoMode, 1},
    {OB_PROP_COLOR_EXPOSURE_INT,            true,   4, PropertyStore::ControlRoute::kZeroOne, 1500},
    {OB_PROP_COLOR_ROLL_INT,                true,  15, PropertyStore::ControlRoute::kZeroOne, 0},
    {OB_PROP_COLOR_AUTO_EXPOSURE_PRIORITY_INT, true, 3, PropertyStore::ControlRoute::kZeroOne, 1},
};
// clang-format on

}  // namespace

PropertyStore::PropertyStore(std::shared_ptr<UsbConnection> conn, UvcTopology topo)
    : conn_(std::move(conn)), topo_(std::move(topo)) {}

PropertyStore::~PropertyStore() = default;

PropertyStore::ControlRoute PropertyStore::routeFor(OBPropertyID id) const {
  ControlRoute route;

  // Depth software filter parameters are implemented in software.
  switch (id) {
    case OB_PROP_DEPTH_SOFT_FILTER_BOOL:
      route.kind = ControlRoute::kSoftware;
      route.software_default = g_soft_filter_enabled.load() ? 1 : 0;
      return route;
    case OB_PROP_DEPTH_MAX_DIFF_INT:
      route.kind = ControlRoute::kSoftware;
      route.software_default = g_soft_filter_max_diff.load();
      return route;
    case OB_PROP_DEPTH_MAX_SPECKLE_SIZE_INT:
      route.kind = ControlRoute::kSoftware;
      route.software_default = g_soft_filter_speckle_size.load();
      return route;
    default:
      break;
  }

  // Standard UVC controls (color camera).
  for (const auto &entry : kUvcRoutes) {
    if (entry.id != id) {
      continue;
    }
    uint8_t unit_id =
        entry.use_camera_terminal ? topo_.control.camera_terminal_id : topo_.control.processing_unit_id;
    if (unit_id == 0) {
      break;  // unit not present on this device
    }
    route.kind = ControlRoute::kUvc;
    route.use_camera_terminal = entry.use_camera_terminal;
    route.selector = entry.selector;
    route.bool_encoding = entry.bool_encoding;
    route.software_default = entry.software_default;
    return route;
  }

  // Everything else (laser, LDP, fan, mirrors, depth/IR exposure, precision,
  // disparity2depth, ...) is firmware-specific. The original SDK transports
  // these through a vendor "GM" host protocol over a UVC extension unit; its
  // command codes are not part of this implementation, so keep a software
  // cache and report the value the caller last stored.
  route.kind = ControlRoute::kSoftware;
  switch (id) {
    case OB_PROP_LASER_BOOL:
      route.software_default = 1;  // emitter is on by default
      break;
    case OB_PROP_DISPARITY_TO_DEPTH_BOOL:
      route.software_default = 1;  // depth stream outputs depth by default
      break;
    case OB_PROP_DEPTH_PRECISION_LEVEL_INT:
      route.software_default = OB_PRECISION_1MM;
      break;
    case OB_PROP_IR_CHANNEL_DATA_SOURCE_INT:
      route.software_default = 0;  // left IR sensor
      break;
    default:
      route.software_default = 0;
      break;
  }
  return route;
}

int32_t PropertyStore::readUvc(const ControlRoute &route) {
  uint8_t unit_id = route.use_camera_terminal ? topo_.control.camera_terminal_id
                                              : topo_.control.processing_unit_id;
  uint8_t buffer[4] = {0, 0, 0, 0};
  uint16_t w_index = static_cast<uint16_t>((unit_id << 8) | topo_.control.interface_number);
  uint16_t w_value = static_cast<uint16_t>(route.selector << 8);
  int transferred = conn_->controlTransfer(0xA1 /*GET|CLASS|INTERFACE*/, 0x81 /*GET_CUR*/, w_value,
                                           w_index, buffer, sizeof(buffer));
  if (transferred != static_cast<int>(sizeof(buffer))) {
    throwError("UVC GET_CUR failed for selector " + std::to_string(route.selector));
  }
  return static_cast<int32_t>(buffer[0] | (buffer[1] << 8) | (buffer[2] << 16) |
                              (static_cast<uint32_t>(buffer[3]) << 24));
}

void PropertyStore::writeUvc(const ControlRoute &route, int32_t value) {
  uint8_t unit_id = route.use_camera_terminal ? topo_.control.camera_terminal_id
                                              : topo_.control.processing_unit_id;
  uint8_t buffer[4] = {static_cast<uint8_t>(value & 0xff),
                       static_cast<uint8_t>((value >> 8) & 0xff),
                       static_cast<uint8_t>((value >> 16) & 0xff),
                       static_cast<uint8_t>((value >> 24) & 0xff)};
  uint16_t w_index = static_cast<uint16_t>((unit_id << 8) | topo_.control.interface_number);
  uint16_t w_value = static_cast<uint16_t>(route.selector << 8);
  int transferred = conn_->controlTransfer(0x21 /*SET|CLASS|INTERFACE*/, 0x01 /*SET_CUR*/, w_value,
                                           w_index, buffer, sizeof(buffer));
  if (transferred != static_cast<int>(sizeof(buffer))) {
    throwError("UVC SET_CUR failed for selector " + std::to_string(route.selector));
  }
}

int32_t PropertyStore::getInt(OBPropertyID id) {
  std::lock_guard<std::mutex> lock(mutex_);
  ControlRoute route = routeFor(id);
  if (route.kind == ControlRoute::kUvc) {
    int32_t value = readUvc(route);
    cache_[static_cast<int>(id)] = value;
    return value;
  }
  auto it = cache_.find(static_cast<int>(id));
  return it != cache_.end() ? it->second : route.software_default;
}

void PropertyStore::setInt(OBPropertyID id, int32_t value) {
  std::lock_guard<std::mutex> lock(mutex_);
  ControlRoute route = routeFor(id);
  if (route.kind == ControlRoute::kUvc) {
    writeUvc(route, value);
  }
  cache_[static_cast<int>(id)] = value;

  // Feed the software depth filter parameters.
  switch (id) {
    case OB_PROP_DEPTH_SOFT_FILTER_BOOL:
      g_soft_filter_enabled.store(value != 0);
      break;
    case OB_PROP_DEPTH_MAX_DIFF_INT:
      g_soft_filter_max_diff.store(value);
      break;
    case OB_PROP_DEPTH_MAX_SPECKLE_SIZE_INT:
      g_soft_filter_speckle_size.store(value);
      break;
    default:
      break;
  }
}

bool PropertyStore::getBool(OBPropertyID id) { return getInt(id) != 0; }

void PropertyStore::setBool(OBPropertyID id, bool value) {
  std::lock_guard<std::mutex> lock(mutex_);
  ControlRoute route = routeFor(id);
  int32_t encoded = value ? 1 : 0;
  if (route.kind == ControlRoute::kUvc) {
    if (route.bool_encoding == ControlRoute::kUvcAutoMode) {
      encoded = value ? 2 : 1;  // UVC AE/AWB mode: 1=manual, 2=auto
    }
    writeUvc(route, encoded);
  }
  cache_[static_cast<int>(id)] = value ? 1 : 0;

  switch (id) {
    case OB_PROP_DEPTH_SOFT_FILTER_BOOL:
      g_soft_filter_enabled.store(value);
      break;
    default:
      break;
  }
}

}  // namespace obsdk

