input.content:
// Calibration loading: external JSON file, else synthesized defaults.
//
// On Astra+/Gemini hardware the original SDK reads binary firmware data
// through internal property 1005 (recovered from AstraUvcDevice::
// initDepthProcessParam in libOrbbecSDK.so.1.5.7); its binary layout was not
// recoverable, so this implementation loads calibration from a JSON file
// (see below) and falls back to clearly-labeled synthesized intrinsics.
#include "ob_internal.h"

#include <cstdlib>
#include <fstream>
#include <sstream>

namespace obsdk {

namespace {

std::string extractObject(const std::string &text, const std::string &key) {
  auto key_pos = text.find('"' + key + '"');
  if (key_pos == std::string::npos) {
    key_pos = text.find(key);
    if (key_pos == std::string::npos) {
      return {};
    }
  }
  auto brace = text.find('{', key_pos);
  if (brace == std::string::npos) {
    return {};
  }
  int depth = 0;
  for (size_t i = brace; i < text.size(); ++i) {
    if (text[i] == '{') {
      ++depth;
    } else if (text[i] == '}') {
      if (--depth == 0) {
        return text.substr(brace, i - brace + 1);
      }
    }
  }
  return {};
}

bool extractNumber(const std::string &text, const std::string &key, float &out) {
  auto key_pos = text.find('"' + key + '"');
  if (key_pos == std::string::npos) {
    key_pos = text.find(key);
    if (key_pos == std::string::npos) {
      return false;
    }
  }
  auto colon = text.find(':', key_pos);
  if (colon == std::string::npos) {
    return false;
  }
  char *end = nullptr;
  float value = std::strtof(text.c_str() + colon + 1, &end);
  if (end == text.c_str() + colon + 1) {
    return false;
  }
  out = value;
  return true;
}

bool extractIntArray(const std::string &text, const std::string &key, float *out, size_t count) {
  auto key_pos = text.find('"' + key + '"');
  if (key_pos == std::string::npos) {
    key_pos = text.find(key);
    if (key_pos == std::string::npos) {
      return false;
    }
  }
  auto bracket = text.find('[', key_pos);
  if (bracket == std::string::npos) {
    return false;
  }
  auto end = text.find(']', bracket);
  if (end == std::string::npos) {
    return false;
  }
  std::string body = text.substr(bracket + 1, end - bracket - 1);
  std::replace(body.begin(), body.end(), ',', ' ');
  std::istringstream stream(body);
  for (size_t i = 0; i < count; ++i) {
    if (!(stream >> out[i])) {
      return false;
    }
  }
  return true;
}

bool parseIntrinsic(const std::string &object, OBCameraIntrinsic &intrinsic) {
  if (object.empty()) {
    return false;
  }
  float fx = 0, fy = 0, cx = 0, cy = 0, w = 0, h = 0;
  if (!extractNumber(object, "fx", fx) || !extractNumber(object, "fy", fy)) {
    return false;
  }
  extractNumber(object, "cx", cx);
  extractNumber(object, "cy", cy);
  extractNumber(object, "width", w);
  extractNumber(object, "height", h);
  intrinsic.fx = fx;
  intrinsic.fy = fy;
  intrinsic.cx = cx;
  intrinsic.cy = cy;
  intrinsic.width = static_cast<int16_t>(w);
  intrinsic.height = static_cast<int16_t>(h);
  return fx > 0.f && fy > 0.f;
}

bool parseDistortion(const std::string &object, OBCameraDistortion &distortion) {
  if (object.empty()) {
    return false;
  }
  extractNumber(object, "k1", distortion.k1);
  extractNumber(object, "k2", distortion.k2);
  extractNumber(object, "k3", distortion.k3);
  extractNumber(object, "k4", distortion.k4);
  extractNumber(object, "k5", distortion.k5);
  extractNumber(object, "k6", distortion.k6);
  extractNumber(object, "p1", distortion.p1);
  extractNumber(object, "p2", distortion.p2);
  return true;
}

bool loadFromJsonFile(const std::string &path, std::vector<OBCameraParam> &out) {
  std::ifstream file(path);
  if (!file) {
    return false;
  }
  std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
  OBCameraParam param{};
  if (!parseIntrinsic(extractObject(content, "depthIntrinsic"), param.depthIntrinsic)) {
    OBSDK_WARN("Calibration file " << path << " has no usable depthIntrinsic");
    return false;
  }
  parseIntrinsic(extractObject(content, "rgbIntrinsic"), param.rgbIntrinsic);
  if (param.rgbIntrinsic.fx == 0.f) {
    param.rgbIntrinsic = param.depthIntrinsic;
  }
  parseDistortion(extractObject(content, "depthDistortion"), param.depthDistortion);
  parseDistortion(extractObject(content, "rgbDistortion"), param.rgbDistortion);

  float baseline = 0.f;
  if (extractNumber(content, "baseline", baseline)) {
    param.transform.trans[0] = baseline;
    param.transform.rot[0] = param.transform.rot[4] = param.transform.rot[8] = 1.f;
  } else {
    float rot[9] = {0}, trans[3] = {0};
    if (extractIntArray(content, "rot", rot, 9) || extractIntArray(content, "rotation", rot, 9)) {
      std::memcpy(param.transform.rot, rot, sizeof(rot));
    } else {
      param.transform.rot[0] = param.transform.rot[4] = param.transform.rot[8] = 1.f;
    }
    if (extractIntArray(content, "trans", trans, 3) ||
        extractIntArray(content, "translation", trans, 3)) {
      std::memcpy(param.transform.trans, trans, sizeof(trans));
    }
  }
  param.isMirrored = false;
  out.push_back(param);
  OBSDK_INFO("Loaded calibration from " << path);
  return true;
}

void synthesizeParams(const DeviceCore &core, std::vector<OBCameraParam> &out) {
  // Pick the first advertised frame size per stream.
  uint32_t depth_w = 640, depth_h = 400;
  uint32_t color_w = 640, color_h = 480;
  bool have_depth = false, have_color = false;
  for (const auto &vs : core.topo.streaming) {
    for (const auto &format : vs.formats) {
      if (format.frames.empty()) {
        continue;
      }
      if (!have_depth && vs.stream_type == OB_STREAM_DEPTH) {
        depth_w = format.frames.front().width;
        depth_h = format.frames.front().height;
        have_depth = true;
      } else if (!have_color && vs.stream_type == OB_STREAM_COLOR) {
        color_w = format.frames.front().width;
        color_h = format.frames.front().height;
        have_color = true;
      }
    }
  }

  // Pinhole approximation (~70 deg horizontal FOV for both imagers). These are
  // NOT factory calibration values; they keep camera_info/point clouds
  // functional until a real calibration file is provided.
  auto makeIntrinsic = [](uint32_t w, uint32_t h, float hfov_deg) {
    OBCameraIntrinsic intrinsic{};
    const float fx = static_cast<float>(w) / (2.f * std::tan(hfov_deg * 3.14159265f / 360.f));
    intrinsic.fx = fx;
    intrinsic.fy = fx;
    intrinsic.cx = static_cast<float>(w) / 2.f - 0.5f;
    intrinsic.cy = static_cast<float>(h) / 2.f - 0.5f;
    intrinsic.width = static_cast<int16_t>(w);
    intrinsic.height = static_cast<int16_t>(h);
    return intrinsic;
  };

  OBCameraParam param{};
  param.depthIntrinsic = makeIntrinsic(depth_w, depth_h, 70.f);
  param.rgbIntrinsic = makeIntrinsic(color_w, color_h, 69.f);
  param.transform.rot[0] = param.transform.rot[4] = param.transform.rot[8] = 1.f;
  param.transform.trans[0] = 75.f;  // nominal Astra+/Gemini baseline in mm
  param.isMirrored = false;
  out.push_back(param);
  OBSDK_WARN("Using SYNTHESIZED calibration (depth " << depth_w << "x" << depth_h << ", color "
                                                     << color_w << "x" << color_h
                                                     << "); set ORBBEC_CALIBRATION_JSON to a real "
                                                        "calibration file for accurate results");
}

}  // namespace

void loadCalibrationParams(const DeviceCorePtr &core, std::vector<OBCameraParam> &out) {
  out.clear();

  // 1. Explicit environment path.
  if (const char *env = std::getenv("ORBBEC_CALIBRATION_JSON")) {
    if (loadFromJsonFile(env, out)) {
      return;
    }
    OBSDK_WARN("ORBBEC_CALIBRATION_JSON points to " << env << " which could not be used");
  }

  // 2. Files next to the working directory, scoped by serial number.
  if (!core->info.serial.empty()) {
    if (loadFromJsonFile("./orbbec_calibration_" + core->info.serial + ".json", out)) {
      return;
    }
  }
  if (loadFromJsonFile("./orbbec_calibration.json", out)) {
    return;
  }

  // 3. Device firmware calibration (property 1005) is not implemented; the
  //    synthesized parameters below keep the node running.
  synthesizeParams(*core, out);
}

}  // namespace obsdk

