void unpackPackedToY16(const uint8_t *src, size_t src_bytes, uint16_t *dst, size_t pixels,
                       int bits) {
  if (!src || !dst || bits < 1 || bits > 16) {
    return;
  }
  if (bits == 16) {
    std::memcpy(dst, src, pixels * 2);
    return;
  }
  if (bits == 8) {
    for (size_t i = 0; i < pixels && i < src_bytes; ++i) {
      dst[i] = src[i];
    }
    return;
  }
  uint64_t accumulator = 0;
  int acc_bits = 0;
  size_t out = 0;
  size_t byte_index = 0;
  const uint64_t mask = (1ull << bits) - 1;
  while (out < pixels) {
    while (acc_bits < bits && byte_index < src_bytes) {
      accumulator |= static_cast<uint64_t>(src[byte_index++]) << acc_bits;
      acc_bits += 8;
    }
    if (acc_bits < bits) {
      break;  // truncated input
    }
    dst[out++] = static_cast<uint16_t>(accumulator & mask);
    accumulator >>= bits;
    acc_bits -= bits;
  }
}

