void unpackPackedToY16(const uint8_t *src, size_t src_bytes, uint16_t *dst, size_t pixels,
                       int bits) {
  if (!src || !dst || bits < 1 || bits > 16) {
    return;
  }
  if (bits == 16) {
    std::memcpy(dst, src, pixels * 2);
    return;
  }
  if (bits == 8) {
    for (size_t i = 0; i < pixels && i < src_bytes; ++i) {
      dst[i] = src[i];
    }
    return;
  }
  // MSB-first continuous bit packing, matching the original SDK's unpackers
  // (y11ToY16: p0 = src[0]<<3 | src[1]>>5, p1 = (src[1]&0x1f)<<6 | src[2]>>2, ...).
  uint64_t accumulator = 0;
  int acc_bits = 0;
  size_t out = 0;
  size_t byte_index = 0;
  const uint64_t mask = (1ull << bits) - 1;
  while (out < pixels) {
    while (acc_bits < bits && byte_index < src_bytes) {
      accumulator = (accumulator << 8) | src[byte_index++];
      acc_bits += 8;
    }
    if (acc_bits < bits) {
      break;  // truncated input
    }
    dst[out++] = static_cast<uint16_t>((accumulator >> (acc_bits - bits)) & mask);
    acc_bits -= bits;
    accumulator &= (1ull << acc_bits) - 1;
  }
}

