// Reference Y11 unpack matching libOrbbecSDK y11ToY16 (16 px / 22 byte groups)
static void refY11(const uint8_t* s, uint16_t* d, int w, int h) {
  int pixels = w * h;
  int i = 0, p = 0;
  while (p < pixels) {
    // process 16 pixels (22 bytes) per group
    for (int k = 0; k < 16 && p < pixels; ++k, ++p) {
      int byteIdx = (k * 11) / 8;
      int bitOff = (k * 11) % 8;
      // read 16 bits starting at bit position k*11 (MSB-first stream)
      int absBit = k * 11;
      int byte0 = s[absBit / 8];
      int next = s[absBit / 8 + 1];
      int val;
      if (bitOff <= 5) { // fits mostly in one byte + spill
        val = ((byte0 << 8) | next) >> (16 - 11 - bitOff);
        val &= 0x7FF;
      } else {
        val = (byte0 << 8 | next) >> (16 - 11 - bitOff);
        val &= 0x7FF;
      }
      d[p] = (uint16_t)val;
    }
    s += 22;
  }
}

