std::shared_ptr<StreamRunner> createUvcRunner(const DeviceCorePtr &core, int streaming_index,
                                              const ProfileSource &source) {
  if (!core) {
    throwError("createUvcRunner: null device core");
  }
  if (streaming_index < 0 ||
      static_cast<size_t>(streaming_index) >= core->topo.streaming.size()) {
    throwError("createUvcRunner: streaming interface index " + std::to_string(streaming_index) +
               " out of range");
  }
  const UvcStreamingInterface &vs = core->topo.streaming[static_cast<size_t>(streaming_index)];
  const UvcFormat *format = nullptr;
  for (const auto &f : vs.formats) {
    if (f.format_index == source.format_index) {
      format = &f;
      break;
    }
  }
  if (!format) {
    throwError("createUvcRunner: no format with index " + std::to_string(source.format_index) +
               " on streaming interface " + std::to_string(streaming_index));
  }
  const UvcFrame *frame = nullptr;
  for (const auto &fr : format->frames) {
    if (fr.frame_index == source.frame_index) {
      frame = &fr;
      break;
    }
  }
  if (!frame) {
    throwError("createUvcRunner: no frame with index " + std::to_string(source.frame_index) +
               " in format " + std::to_string(source.format_index));
  }
  uint32_t interval = source.interval;
  if (interval == 0 && !frame->intervals.empty()) {
    interval = frame->intervals.front();
  }
  OBStreamType stream_type = vs.stream_type;
  if (stream_type == OB_STREAM_UNKNOWN) {
    stream_type = classifyStream(core->topo, vs, *format);
  }
  return std::make_shared<UvcStreamRunner>(core, vs, *format, *frame, interval, stream_type);
}

OBStreamType classifyStream(const UvcTopology &topo, const UvcStreamingInterface &vs,
                            const UvcFormat &format) {
  // (a) Name-based: the output terminal linked by bTerminalLink, its source
  // (one level up the terminal chain), or the camera terminal.
  std::string name;
  if (const UvcTerminal *out = findTerminal(topo.control, vs.terminal_link)) {
    name = out->name;
    if (name.empty() && out->source_id != 0) {
      if (const UvcTerminal *src = findTerminal(topo.control, out->source_id)) {
        name = src->name;
      }
    }
  }
  if (name.empty()) {
    if (const UvcTerminal *cam = findTerminal(topo.control, topo.control.camera_terminal_id)) {
      name = cam->name;
    }
  }
  if (nameMatches(name, "depth", "深度")) {
    return OB_STREAM_DEPTH;
  }
  if (nameMatches(name, "ir", "红外") || nameMatches(name, "infrared", nullptr)) {
    return OB_STREAM_IR;
  }
  if (nameMatches(name, "color", "彩色") || nameMatches(name, "rgb", nullptr)) {
    return OB_STREAM_COLOR;
  }

  // (b) Compressed / interleaved color formats are color streams.
  switch (format.ob_format) {
    case OB_FORMAT_MJPG:
    case OB_FORMAT_YUYV:
    case OB_FORMAT_UYVY:
    case OB_FORMAT_NV12:
    case OB_FORMAT_NV21:
    case OB_FORMAT_I420:
    case OB_FORMAT_RGB:
    case OB_FORMAT_BGR:
      return OB_STREAM_COLOR;
    default:
      break;
  }

  // (c) Unknown: DeviceCore applies its product-specific fallback.
  return OB_STREAM_UNKNOWN;
}

