// Validates parseUvcTopology/classifyStream against a synthetic Gemini-style
// UVC config descriptor (VC + 3 VS interfaces: MJPG color, Y11 depth, Y10 IR).
#include "ob_internal.h"
#include <cassert>
#include <cstdio>
#include <cstring>
#include <vector>

using namespace obsdk;

static void put8(std::vector<uint8_t> &v, uint8_t x) { v.push_back(x); }
static void put16(std::vector<uint8_t> &v, uint16_t x) { v.push_back(x & 0xff); v.push_back(x >> 8); }
static void put32(std::vector<uint8_t> &v, uint32_t x) {
  for (int i = 0; i < 4; ++i) v.push_back((x >> (8 * i)) & 0xff);
}
static void patch16(std::vector<uint8_t> &v, size_t at, uint16_t x) { v[at] = x & 0xff; v[at+1] = x >> 8; }
static void patch32(std::vector<uint8_t> &v, size_t at, uint32_t x) {
  for (int i = 0; i < 4; ++i) v[at+i] = (x >> (8 * i)) & 0xff;
}

// MS-video vendor GUID with ASCII fourcc in the first 4 bytes
static void putVendorGuid(std::vector<uint8_t> &v, const char *fourcc) {
  for (int i = 0; i < 4; ++i) v.push_back((uint8_t)fourcc[i]);
  for (int i = 0; i < 12; ++i) {
    static const uint8_t suffix[12] = {0,0,0x10,0x80,0,0,0xaa,0,0x38,0x9b,0x71,0};
    v.push_back(suffix[i]);
  }
}

static void putVsInterface(std::vector<uint8_t> &v, uint8_t iface, uint8_t ep,
                           uint8_t termLink, const char *fourcc, uint8_t bpp,
                           uint16_t w, uint16_t h, uint8_t descSubtype /*0x06 mjpg, 0x00 vendor*/) {
  // Interface alt 0 (no endpoints)
  put8(v, 9); put8(v, 4); put8(v, iface); put8(v, 0); put8(v, 0); put8(v, 0x0E); put8(v, 0x02); put8(v, 0); put8(v, 0);
  // VS_INPUT_HEADER (13 bytes, 1 format)
  size_t hdr = v.size();
  put8(v, 13); put8(v, 0x24); put8(v, 0x01); put8(v, 1);
  put16(v, 0); // wTotalLength placeholder
  put8(v, ep); put8(v, 0); put8(v, termLink); put8(v, 0); put8(v, 0); put8(v, 0); put8(v, 0);
  size_t fmtStart = v.size();
  // format descriptor (27 bytes): index, numFrames, guid, bpp, defaults...
  put8(v, 27); put8(v, 0x24); put8(v, descSubtype); put8(v, 1); put8(v, 1);
  putVendorGuid(v, fourcc);
  put8(v, bpp); put8(v, 0); put8(v, 0); put8(v, 0); put8(v, 0); put8(v, 0); put8(v, 0);
  // frame descriptor discrete: 26 + 4 = 30 bytes
  put8(v, 30); put8(v, 0x24); put8(v, descSubtype); put8(v, 1); put8(v, 0);
  put16(v, w); put16(v, h);
  put32(v, 10000000); put32(v, 10000000); put32(v, (uint32_t)w * h * 2);
  put32(v, 333333); put8(v, 1); put32(v, 333333);
  // color matching (6)
  put8(v, 6); put8(v, 0x24); put8(v, 0x0D); put8(v, 1); put8(v, 1); put8(v, 4);
  size_t vsEnd = v.size();
  patch16(v, hdr + 4, (uint16_t)(vsEnd - fmtStart + 8)); // wTotalLength (header+formats)
  // alt 1 with isoc endpoint
  put8(v, 9); put8(v, 4); put8(v, iface); put8(v, 1); put8(v, 1); put8(v, 0x0E); put8(v, 0x02); put8(v, 0); put8(v, 0);
  put8(v, 7); put8(v, 5); put8(v, ep); put16(v, 3072); put8(v, 0); put8(v, 0);
}

int main() {
  std::vector<uint8_t> d;
  // ---- config descriptor (fill wTotalLength later) ----
  put8(d, 9); put8(d, 2); put16(d, 0); put8(d, 4); put8(d, 1); put8(d, 0); put8(d, 0x80); put8(d, 50);
  // IAD
  put8(d, 8); put8(d, 0x0B); put8(d, 0); put8(d, 4); put8(d, 0x0E); put8(d, 0x01); put8(d, 0x00); put8(d, 0);
  // VC interface alt0
  put8(d, 9); put8(d, 4); put8(d, 0); put8(d, 0); put8(d, 0); put8(d, 0x0E); put8(d, 0x01); put8(d, 0x00); put8(d, 0);
  // VC_HEADER (12)
  put8(d, 12); put8(d, 0x24); put8(d, 0x01); put16(d, 0x0100); put16(d, 50); put32(d, 48000000); put8(d, 0);
  // INPUT_TERMINAL camera (15)
  put8(d, 15); put8(d, 0x24); put8(d, 0x02); put8(d, 1); put16(d, 0x0201); put8(d, 0);
  put16(d, 0); put16(d, 0); put16(d, 0); put8(d, 0); put8(d, 0);
  // PROCESSING_UNIT (11, controlSize 2)
  put8(d, 11); put8(d, 0x24); put8(d, 0x05); put8(d, 2); put8(d, 1); put16(d, 0); put8(d, 2);
  put8(d, 0x03); put8(d, 0x00); put8(d, 0);
  // OUTPUT_TERMINALs -> streaming out x3 (9 each), sourced from PU 2
  for (uint8_t id = 3; id <= 5; ++id) {
    put8(d, 9); put8(d, 0x24); put8(d, 0x03); put8(d, id); put16(d, 0x0101); put8(d, 2); put8(d, 0);
  }
  // EXTENSION_UNIT (26: nrPins=1, ctlSize=2)
  put8(d, 26); put8(d, 0x24); put8(d, 0x06); put8(d, 7);
  for (int i = 0; i < 16; ++i) put8(d, (uint8_t)(0xA0 + i));  // guid bytes
  put8(d, 2); put8(d, 2); put8(d, 1); put8(d, 2); put8(d, 0x0F); put8(d, 0x00); put8(d, 0);
  // VS color (MJPG 640x480) iface 1, ep 0x81, link OT3
  putVsInterface(d, 1, 0x81, 3, "MJPG",  0,  640, 480, 0x06);
  // VS depth (Y11 640x400) iface 2, ep 0x82, link OT4
  putVsInterface(d, 2, 0x82, 4, "Y11 ", 11,  640, 400, 0x00);
  // VS IR (Y10 640x400) iface 3, ep 0x83, link OT5
  putVsInterface(d, 3, 0x83, 5, "Y10 ", 10,  640, 400, 0x00);
  patch16(d, 2, (uint16_t)d.size());

  UvcTopology topo = parseUvcTopology(d);
  assert(topo.valid);
  printf("VC iface %u, PU %u, camera term %u, XUs %zu, VS count %zu\n",
         topo.control.interface_number, topo.control.processing_unit_id,
         topo.control.camera_terminal_id, topo.control.extension_units.size(),
         topo.streaming.size());
  assert(topo.streaming.size() == 3);
  assert(topo.control.processing_unit_id == 2);
  assert(topo.control.extension_units.size() == 1);
  assert(topo.control.extension_units[0].unit_id == 7);

  // formats/frames survived
  int found_mjpg = 0, found_y11 = 0, found_y10 = 0;
  for (const auto &vs : topo.streaming) {
    assert(!vs.alt_settings.empty());
    bool has_ep = false;
    for (const auto &alt : vs.alt_settings) if (alt.endpoint_address == (vs.interface_number == 1 ? 0x81 : vs.interface_number == 2 ? 0x82 : 0x83)) has_ep = true;
    assert(has_ep);
    assert(vs.formats.size() == 1);
    const auto &f = vs.formats[0];
    assert(f.frames.size() == 1);
    assert(f.frames[0].intervals.size() == 1 && f.frames[0].intervals[0] == 333333);
    if (f.ob_format == OB_FORMAT_MJPG) { found_mjpg++; assert(f.frames[0].width == 640 && f.frames[0].height == 480); }
    if (f.ob_format == OB_FORMAT_Y11) { found_y11++; assert(f.bits_per_pixel == 11 && f.frames[0].width == 640 && f.frames[0].height == 400); }
    if (f.ob_format == OB_FORMAT_Y10) { found_y10++; assert(f.bits_per_pixel == 10 && f.frames[0].height == 400); }
    // classification without names falls back to format heuristics
    OBStreamType t = classifyStream(topo, vs, f);
    if (f.ob_format == OB_FORMAT_MJPG) assert(t == OB_STREAM_COLOR);
    printf("VS iface %u format=%d bpp=%u classified=%d\n", vs.interface_number, (int)f.ob_format,
           f.bits_per_pixel, (int)t);
  }
  assert(found_mjpg == 1 && found_y11 == 1 && found_y10 == 1);
  printf("ALL UVC DESCRIPTOR TESTS PASSED\n");
  return 0;
}
EOF
