 ~UvcStreamRunner() override { stop(); }

 void start(RawFrameCallback cb) override {
   bool expected = false;
   if (!running_.compare_exchange_strong(expected, true)) {
     throwError("UvcStreamRunner: stream is already running");
   }
   stopping_ = false;
   cb_ = std::move(cb);
   try {
     conn_ = core_->connection();
     fd_ = conn_->fd();

     // Pick the altsetting with the largest wMaxPacketSize that carries a
     // real data endpoint.
     const UvcStreamingInterface::AltSetting *best = nullptr;
     for (const auto &alt : vs_.alt_settings) {
       if (alt.endpoint_address == 0) {
         continue;
       }
       if (best == nullptr || alt.max_packet_size > best->max_packet_size) {
         best = &alt;
       }
     }
     if (best == nullptr) {
       throwError("UvcStreamRunner: VS interface " + std::to_string(vs_.interface_number) +
                  " has no altsetting with a data endpoint");
     }
     if (best->max_packet_size == 0) {
       throwError("UvcStreamRunner: VS interface data endpoint reports wMaxPacketSize 0");
     }
     alt_ = *best;
     max_packet_ = std::min<uint16_t>(alt_.max_packet_size, kMaxPacketCap);
     isoc_ = (alt_.attributes & 0x03) == 2;

     conn_->detachKernelDriver(vs_.interface_number);
     if (!conn_->claimInterface(vs_.interface_number)) {
       throwError("UvcStreamRunner: cannot claim interface " +
                  std::to_string(vs_.interface_number) + ": " + strerror(errno) +
                  " (is another process streaming?)");
     }
     claimed_ = true;
     conn_->setInterface(vs_.interface_number, alt_.alternate);

     // Reassembler configuration.
     int bits = bitsForFormat(format_.ob_format, format_.bits_per_pixel);
     raw_expected_ = !isCompressedFormat(format_.ob_format) && bits > 0;
     expected_ = 0;
     if (raw_expected_) {
       expected_ = (static_cast<size_t>(frame_.width) * frame_.height *
                    static_cast<size_t>(bits) + 7) / 8;
     }
     accum_.clear();
     have_fid_ = false;
     current_fid_ = false;

     OBSDK_INFO("UvcStreamRunner: iface "
                << static_cast<int>(vs_.interface_number) << " alt "
                << static_cast<int>(alt_.alternate) << " ep 0x" << std::hex
                << static_cast<int>(alt_.endpoint_address) << std::dec << " mps " << max_packet_
                << (isoc_ ? " isoc" : " bulk") << " " << frame_.width << "x" << frame_.height
                << " fmt " << static_cast<int>(format_.ob_format) << " @" << interval_
                << " (100ns)");

     if (isoc_) {
       setupIsoc();
     }
     // Bulk needs no pre-allocated URBs; the worker issues USBDEVFS_BULK.
   } catch (...) {
     cleanupSetup();
     running_ = false;
     throw;
   }
   worker_ = std::thread([this] {
     if (isoc_) {
       isocLoop();
     } else {
       bulkLoop();
     }
   });
 }

 void stop() override {
   if (!running_.exchange(false)) {
     return;  // never started, or already stopped (idempotent)
   }
   stopping_ = true;
   // Unlink pending isoc URBs so the worker's reap loop can drain them.
   if (isoc_ && fd_ >= 0) {
     for (int u = 0; u < kIsoUrbCount; ++u) {
       if (submitted_[u]) {
         ::ioctl(fd_, USBDEVFS_DISCARDURB, urbs_[static_cast<size_t>(u)].urb());
       }
     }
   }
   if (worker_.joinable()) {
     worker_.join();
   }
   // The worker drained reaped URBs on its way out; discard+drain once more
   // to cover a URB the worker requeued just before seeing the stop flag.
   if (isoc_ && fd_ >= 0) {
     for (int u = 0; u < kIsoUrbCount; ++u) {
       if (submitted_[u]) {
         ::ioctl(fd_, USBDEVFS_DISCARDURB, urbs_[static_cast<size_t>(u)].urb());
       }
     }
     drainReapedIsoc();
   }
   if (claimed_ && conn_) {
     conn_->releaseInterface(vs_.interface_number);
     claimed_ = false;
   }
   cb_ = nullptr;
   conn_.reset();
   fd_ = -1;
 }

private:
 // -------------------------------------------------------------------------
 // Setup / teardown
 // -------------------------------------------------------------------------

 void setupIsoc() {
   urbs_.resize(kIsoUrbCount);
   buffers_.resize(kIsoUrbCount);
   for (int u = 0; u < kIsoUrbCount; ++u) {
     IsoUrbStorage &storage = urbs_[static_cast<size_t>(u)];
     std::memset(storage.raw, 0, sizeof(storage.raw));
     buffers_[static_cast<size_t>(u)].assign(
         static_cast<size_t>(max_packet_) * kPacketsPerUrb, 0);
     usbdevfs_urb *urb = storage.urb();

// usbdevfs_urb ends with a zero-length iso_frame_desc[] array; storage for the
// kPacketsPerUrb real packet descriptors is placed directly behind the fixed
// urb fields, which is what the kernel expects for SUBMITURB.
struct IsoUrbStorage {
  alignas(8) uint8_t raw[sizeof(usbdevfs_urb) +
                         kPacketsPerUrb * sizeof(usbdevfs_iso_packet_desc)];
  usbdevfs_urb *urb() { return reinterpret_cast<usbdevfs_urb *>(raw); }
  const usbdevfs_urb *urb() const { return reinterpret_cast<const usbdevfs_urb *>(raw); }
  usbdevfs_iso_packet_desc *packets() {
    return reinterpret_cast<usbdevfs_iso_packet_desc *>(raw + sizeof(usbdevfs_urb));
  }
};

// ---------------------------------------------------------------------------
// Frame typing / sizing helpers
// ---------------------------------------------------------------------------

OBFrameType frameTypeFor(OBStreamType stream_type) {
  switch (stream_type) {
    case OB_STREAM_DEPTH: return OB_FRAME_DEPTH;
    case OB_STREAM_COLOR: return OB_FRAME_COLOR;
    case OB_STREAM_IR:
    case OB_STREAM_IR_LEFT:
    case OB_STREAM_IR_RIGHT: return OB_FRAME_IR;
    default: return OB_FRAME_VIDEO;
  }
}

// Bits per pixel for frame-size computation; 0 means "unknown / not raw".
int bitsForFormat(OBFormat f, uint8_t descriptor_bpp) {
  switch (f) {
    case OB_FORMAT_Y8: return 8;
    case OB_FORMAT_Y10: return 10;
    case OB_FORMAT_Y11: return 11;
    case OB_FORMAT_Y12: return 12;
    case OB_FORMAT_Y14: return 14;
    case OB_FORMAT_Y16: return 16;
    case OB_FORMAT_YUYV:
    case OB_FORMAT_UYVY: return 16;
    case OB_FORMAT_NV12:
    case OB_FORMAT_NV21:
    case OB_FORMAT_I420: return 12;
    case OB_FORMAT_RGB:
    case OB_FORMAT_BGR: return 24;
    default: return descriptor_bpp;  // vendor packed formats report their bpp
  }
}

bool isCompressedFormat(OBFormat f) {
  switch (f) {
    case OB_FORMAT_MJPG:
    case OB_FORMAT_H264:
    case OB_FORMAT_H265:
    case OB_FORMAT_HEVC:
    case OB_FORMAT_COMPRESSED:
    case OB_FORMAT_UNKNOWN:
      return true;
    default:
      return false;
  }
}

// ---------------------------------------------------------------------------
// UvcStreamRunner: one usbfs capture loop per streaming interface
