class UvcStreamRunner : public StreamRunner {
 public:
  UvcStreamRunner(const DeviceCorePtr &core, const UvcStreamingInterface &vs,
                  const UvcFormat &format, const UvcFrame &frame, uint32_t interval,
                  OBStreamType stream_type)
