// Pairs OpenNI depth devices (e.g. Gemini 0x0614) with their color companion
// device (0x0511). Companions stay in the list (they need to be openable) but
// carry a paired marker; makeDeviceList hides them from user enumeration.
namespace {
// sysfs basename, e.g. "3-1.4" or "2-1.4.2" (USB physical path).
std::string usbPath(const UsbDeviceInfo &info) {
  auto slash = info.sysfs_path.find_last_of('/');
  return slash == std::string::npos ? info.sysfs_path : info.sysfs_path.substr(slash + 1);
}

// Number of leading path components shared, e.g. "3-1.4" vs "3-1.4.1" -> 1.
int sharedPathPrefix(const std::string &a, const std::string &b) {
  if (a.rfind(b, 0) == 0 || b.rfind(a, 0) == 0) {
    return 1;  // one is a subtree of the other
  }
  size_t n = std::min(a.size(), b.size());
  size_t i = 0;
  for (; i < n; ++i) {
    if (a[i] != b[i]) {
      break;
    }
  }
  // require a component boundary ('.' or '-')
  return i > 0 && (i == n || a[i] == '.' || a[i] == '-' || b[i] == '.' || b[i] == '-') ? 1 : 0;
}
}  // namespace

void pairOpenNICompanions(std::vector<UsbDeviceInfo> &devices) {
  for (auto &depth : devices) {
    if (!isOpenNIDepthPid(depth.pid)) {
      continue;
    }
    const UsbDeviceInfo *best = nullptr;
    int best_score = -1;
    std::string depth_path = usbPath(depth);
