234	void OpenNIVendorVideoPort::processBulkData(unsigned char* data, int length) {
235	    // Parse "RB" (0x52 0x42) packets from bulk data
236	    size_t offset = 0;
237	    while(offset + 2 <= (size_t)length) {
238	        if(data[offset] == 0x52 && data[offset + 1] == 0x42) {
239	            // Found "RB" packet header
240	            if(offset + PACKET_HEADER_SIZE <= (size_t)length) {
241	                size_t dataStart = offset + PACKET_HEADER_SIZE;
242	                // Find next "RB" to determine packet end
243	                size_t packetEnd = (size_t)length;
244	                for(size_t k = dataStart + 1; k + 1 < (size_t)length; k++) {
245	                    if(data[k] == 0x52 && data[k + 1] == 0x42) {
246	                        packetEnd = k;
247	                        break;
248	                    }
249	                }
250	                size_t pixelLen = packetEnd - dataStart;
251	                if(pixelLen > 0 && frameBuffer_.size() + pixelLen <= expectedFrameSize_ * 2) {
252	                    frameBuffer_.insert(frameBuffer_.end(), data + dataStart, data + dataStart + pixelLen);
253	                }
254	
255	                // Complete frame?
256	                if(frameBuffer_.size() >= expectedFrameSize_) {
257	                    auto frame = FrameFactory::createFrameFromStreamProfile(currentProfile_);
258	                    auto vf = frame->as<VideoFrame>();
259	                    vf->updateData(frameBuffer_.data(), expectedFrameSize_);
260	                    vf->setNumber(frameIndex_++);
261	                    auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
262	                        std::chrono::system_clock::now().time_since_epoch()).count();
263	                    vf->setTimeStampUsec(static_cast<uint64_t>(now * 1000));
264	                    if(callback_) callback_(frame);
265	                    frameBuffer_.clear();
266	                }
267	                offset = packetEnd;
268	            } else {
269	                offset += 2;
270	            }
271	        } else {
272	            offset++;
273	        }
274	    }
275	}
