// -------------------------------------------------------------------------
// Gemini vendor bulk runner
// -------------------------------------------------------------------------
class VendorNiRunner : public StreamRunner {
 public:
  VendorNiRunner(DeviceCorePtr core, OBSensorType sensor_type, uint32_t width, uint32_t height)
      : core_(std::move(core)),
        sensor_type_(sensor_type),
        width_(width),
        height_(height),
        expected_(static_cast<size_t>(width) * height * 2) {}

  ~VendorNiRunner() override { stop(); }

  void start(RawFrameCallback cb) override {
    bool expected = false;
    if (!running_.compare_exchange_strong(expected, true)) {
      throwError("VendorNiRunner: stream is already running");
    }
    stop_requested_ = false;
    cb_ = std::move(cb);
    try {
      conn_ = core_->connection();
      fd_ = conn_->fd();
      if (fd_ < 0) {
        throwError("VendorNiRunner: device is not open");
      }
      sendInitCommands();
      setupIsocBulks();
    } catch (...) {
      cleanup();
      running_ = false;
      throw;
    }
    worker_ = std::thread([this]() { bulkLoop(); });
    OBSDK_INFO("VendorNiRunner: streaming " << width_ << "x" << height_ << " Z16 over bulk ep 0x"
                                            << std::hex << kBulkEndpoint << std::dec);
  }

  void stop() override {
    if (!running_.exchange(false)) {
      return;
    }
    stop_requested_ = true;
    for (int u = 0; u < kUrbCount; ++u) {
      if (submitted_[u]) {
        ::ioctl(fd_, USBDEVFS_DISCARDURB, &urbs_[static_cast<size_t>(u)]);
      }
    }
    if (worker_.joinable()) {
      worker_.join();
    }
    cleanup();
    cb_ = nullptr;
    conn_.reset();
    fd_ = -1;
  }

 private:
  void sendInitCommands() {
    // 55 hardcoded commands (seq 0x00..0x27), then the 105 generated
    // transfer-buffer commands (seq 0x28..0x90).
    uint8_t send_buf[32];
    uint8_t recv_buf[64];
    size_t sent = 0;
    for (const char *hex : kGeminiGmCommands) {
      size_t len = 0;
      if (!hexToBytes(hex, send_buf, sizeof(send_buf), len) || len == 0) {
        throwError("VendorNiRunner: malformed GM command table entry");
      }
      int transferred =
          conn_->controlTransfer(0x40, 0, 0, 0, send_buf, static_cast<uint16_t>(len), 5000);
      if (transferred != static_cast<int>(len)) {
        throwError("VendorNiRunner: GM command " + std::to_string(sent) + " OUT failed");
      }
      // Response read is best-effort: some commands answer, some stay silent.
      conn_->controlTransfer(0xC0, 0, 0, 0, recv_buf, sizeof(recv_buf), 5000);
      ++sent;
    }
    for (int i = 0; i < 105; ++i) {
      uint16_t seq = static_cast<uint16_t>(0x28 + i);
      uint16_t counter = static_cast<uint16_t>(i * 0x40);
      uint8_t cmd[14] = {0x47, 0x4d, 0x03, 0x00, 0x19, 0x00,
                         static_cast<uint8_t>(seq & 0xff), static_cast<uint8_t>(seq >> 8),
                         static_cast<uint8_t>(counter & 0xff), static_cast<uint8_t>(counter >> 8),
                         0x07, 0x00, static_cast<uint8_t>(i == 104 ? 0x18 : 0x20), 0x00};
      int transferred =
          conn_->controlTransfer(0x40, 0, 0, 0, cmd, sizeof(cmd), 5000);
      if (transferred != static_cast<int>(sizeof(cmd))) {
        throwError("VendorNiRunner: GM buffer-config command " + std::to_string(i) +
                   " OUT failed");
      }
      conn_->controlTransfer(0xC0, 0, 0, 0, recv_buf, sizeof(recv_buf), 5000);
      ++sent;
    }
    OBSDK_INFO("VendorNiRunner: sent " << sent << " GM init commands");
  }

  void setupIsocBulks() {
    for (int u = 0; u < kUrbCount; ++u) {
      std::memset(&urbs_[static_cast<size_t>(u)], 0, sizeof(usbdevfs_urb));
      buffers_[static_cast<size_t>(u)].assign(kBulkBufferSize, 0);
      usbdevfs_urb &urb = urbs_[static_cast<size_t>(u)];
      urb.type = USBDEVFS_URB_TYPE_BULK;
      urb.endpoint = kBulkEndpoint;
      urb.buffer = buffers_[static_cast<size_t>(u)].data();
      urb.buffer_length = kBulkBufferSize;
      if (::ioctl(fd_, USBDEVFS_SUBMITURB, &urb) < 0) {
        throwError("VendorNiRunner: USBDEVFS_SUBMITURB failed: " + std::string(strerror(errno)));
      }
      submitted_[static_cast<size_t>(u)] = true;
    }
  }

  void bulkLoop() {
    int poll_failures = 0;
    while (!stop_requested_) {
      pollfd pfd{};
      pfd.fd = fd_;
      pfd.events = POLLOUT;
      int pr = ::poll(&pfd, 1, 200);
      if (pr < 0) {
        if (errno == EINTR) {
          continue;
        }
        OBSDK_ERROR("VendorNiRunner: poll failed: " << strerror(errno));
        break;
      }
      if (pr == 0) {
        if (++poll_failures > 50) {
          OBSDK_ERROR("VendorNiRunner: poll timed out repeatedly; stopping capture");
          break;
        }
        continue;
      }
      poll_failures = 0;
      usbdevfs_urb *reaped = nullptr;
      while (::ioctl(fd_, USBDEVFS_REAPURBNDELAY, &reaped) == 0) {
        if (reaped != nullptr && reaped->status == 0 && reaped->actual_length > 0) {
          processBulkData(static_cast<const uint8_t *>(reaped->buffer),
                          static_cast<size_t>(reaped->actual_length));
        }
        if (reaped != nullptr) {
          // Resubmit immediately.
          reaped->actual_length = 0;
          reaped->status = 0;
          reaped->buffer_length = kBulkBufferSize;
          if (!stop_requested_ && ::ioctl(fd_, USBDEVFS_SUBMITURB, reaped) < 0) {
            if (errno != EBUSY && errno != ENODEV) {
              OBSDK_WARN("VendorNiRunner: resubmit failed: " << strerror(errno));
            }
          } else if (stop_requested_) {
            markUnsubmitted(reaped);
          }
        }
        if (stop_requested_) {
          break;
        }
      }
    }
  }

  void markUnsubmitted(usbdevfs_urb *urb) {
    for (int u = 0; u < kUrbCount; ++u) {
      if (&urbs_[static_cast<size_t>(u)] == urb) {
        submitted_[static_cast<size_t>(u)] = false;
      }
    }
  }

  // Scans for "RB" packets (16-byte header + payload), accumulates pixel data
  // and delivers a frame at width*height*2 bytes. Any residual bytes beyond
  // the frame boundary start the next frame.
  void processBulkData(const uint8_t *data, size_t length) {
    size_t offset = 0;
    while (offset + 2 <= length) {
      if (data[offset] != 0x52 || data[offset + 1] != 0x42) {
        ++offset;
        continue;
      }
      if (offset + static_cast<size_t>(kPacketHeaderSize) > length) {
        break;
      }
      size_t data_start = offset + kPacketHeaderSize;
      size_t packet_end = length;
      for (size_t k = data_start + 1; k + 1 < length; ++k) {
        if (data[k] == 0x52 && data[k + 1] == 0x42) {
          packet_end = k;
          break;
        }
      }
      size_t pixel_len = packet_end - data_start;
      if (pixel_len > 0 && frame_buffer_.size() + pixel_len <= expected_ * kMaxCarryBytesFactor) {
        frame_buffer_.insert(frame_buffer_.end(), data + data_start, data + data_start + pixel_len);
      }
      if (frame_buffer_.size() >= expected_) {
        deliverFrame();
        size_t excess = frame_buffer_.size() - expected_;
        if (excess > 0) {
          std::memmove(frame_buffer_.data(), frame_buffer_.data() + expected_, excess);
        }
        frame_buffer_.resize(excess);
      }
      offset = packet_end;
    }
  }

  void deliverFrame() {
    if (!cb_ || frame_buffer_.size() < expected_) {
      return;
    }
    RawFrame raw;
    raw.type = sensor_type_ == OB_SENSOR_IR ? OB_FRAME_IR : OB_FRAME_DEPTH;
    raw.format = OB_FORMAT_Y16;  // wire format is 16-bit Z16
    raw.width = width_;
    raw.height = height_;
    raw.system_time_ms = wallClockMs();
    raw.data = std::make_shared<std::vector<uint8_t>>(frame_buffer_.begin(),
                                                      frame_buffer_.begin() + expected_);
    cb_(raw);
  }

  void cleanup() {
    if (fd_ >= 0) {
      for (int u = 0; u < kUrbCount; ++u) {
        if (submitted_[static_cast<size_t>(u)]) {
          ::ioctl(fd_, USBDEVFS_DISCARDURB, &urbs_[static_cast<size_t>(u)]);
        }
        submitted_[static_cast<size_t>(u)] = false;
      }
      // Drain completed URBs so their buffers are not referenced anymore.
      usbdevfs_urb *reaped = nullptr;
      while (::ioctl(fd_, USBDEVFS_REAPURBNDELAY, &reaped) == 0) {
      }
    }
  }

  DeviceCorePtr core_;
  OBSensorType sensor_type_;
  uint32_t width_;
  uint32_t height_;
  size_t expected_;

  std::shared_ptr<UsbConnection> conn_;
  int fd_ = -1;
  RawFrameCallback cb_;
  std::atomic<bool> running_{false};
  std::atomic<bool> stop_requested_{false};
  std::thread worker_;

  usbdevfs_urb urbs_[kUrbCount];
  std::vector<uint8_t> buffers_[kUrbCount];
  bool submitted_[kUrbCount] = {false};

  std::vector<uint8_t> frame_buffer_;
};

}  // namespace

std::shared_ptr<StreamRunner> createVendorNiRunner(const DeviceCorePtr &core,
                                                   OBSensorType sensor_type,
                                                   const ProfileSource &source,
                                                   uint32_t width, uint32_t height) {
  (void)source;
  if (!core) {
    throwError("createVendorNiRunner: null device core");
  }
  if (core->klass != ProductClass::kGeminiOpenNI) {
    throwError("createVendorNiRunner: device is not an OpenNI vendor device");
  }
  return std::make_shared<VendorNiRunner>(core, sensor_type, width, height);
}

