          impl->height = mode.height;
          impl->fps = mode.fps;
          impl->source.streaming_interface = -1;  // vendor bulk, not a UVC VS interface
          impl->source.interval = 10000000u / mode.fps;
          ProfileEntry entry;
          entry.source = impl->source;
          entry.owner = shared_from_this();
          ob::StreamProfile base(std::move(impl));
          auto video = std::make_shared<ob::VideoStreamProfile>(base);
          created_sources.emplace_back(video.get(), entry);
          list_impl->profiles.push_back(video);
        }
      }
    } else if (type == OB_SENSOR_COLOR && companion) {
      // Color profiles come from the paired UVC companion device.
      std::lock_guard<std::mutex> lock(profile_mutex);
      auto list = companion->profilesFor(OB_SENSOR_COLOR);
      profile_lists[type] = list;
      return list;
    }
  } else {
    for (size_t vs_index = 0; vs_index < topo.streaming.size(); ++vs_index) {
      const auto &vs = topo.streaming[vs_index];
      if (vs.stream_type == OB_STREAM_UNKNOWN) {
        continue;
      }
      OBSensorType sensor_type = OB_SENSOR_UNKNOWN;
      switch (vs.stream_type) {
        case OB_STREAM_DEPTH:
          sensor_type = OB_SENSOR_DEPTH;
          break;
        case OB_STREAM_COLOR:
          sensor_type = OB_SENSOR_COLOR;
          break;
        case OB_STREAM_IR:
        case OB_STREAM_IR_LEFT:
        case OB_STREAM_IR_RIGHT:
          sensor_type = OB_SENSOR_IR;
          break;
        default:
          continue;
      }
      if (sensor_type != type) {
        continue;
      }
      for (const auto &format : vs.formats) {
        std::vector<OBFormat> offered = {format.ob_format};
        // The SDK unpacks packed depth/IR formats to Y16 by default, so expose
        // Y16 aliases for packed formats (matches the original profile lists).
        switch (format.ob_format) {
          case OB_FORMAT_Y10:
          case OB_FORMAT_Y11:
          case OB_FORMAT_Y12:
          case OB_FORMAT_Y14:
          case OB_FORMAT_RLE:
            offered.push_back(OB_FORMAT_Y16);
            break;
          default:
            break;
        }
        for (const auto &frame : format.frames) {
          if (frame.intervals.empty()) {
            continue;
          }
          for (uint32_t interval : frame.intervals) {
            uint32_t fps =
                interval > 0 ? static_cast<uint32_t>((10000000u + interval / 2) / interval) : 0;
            for (OBFormat offered_format : offered) {
              auto impl = std::make_unique<StreamProfileImpl>();
              impl->stream_type = vs.stream_type;
              impl->format = offered_format;
              impl->width = frame.width;
              impl->height = frame.height;
              impl->fps = fps;
              impl->source.streaming_interface = static_cast<int>(vs_index);
              impl->source.format_index = format.format_index;
              impl->source.frame_index = frame.frame_index;
              impl->source.interval = interval;
              ProfileEntry entry;
              entry.source = impl->source;
              entry.owner = shared_from_this();
              ob::StreamProfile base(std::move(impl));
              auto video = std::make_shared<ob::VideoStreamProfile>(base);
              created_sources.emplace_back(video.get(), entry);
              list_impl->profiles.push_back(video);
            }
          }
        }
      }
    }
  }

  std::lock_guard<std::mutex> lock(profile_mutex);
  for (const auto &entry : created_sources) {
    profile_sources[entry.first] = entry.second;
  }
  auto list = std::make_shared<ob::StreamProfileList>(std::move(list_impl));
  profile_lists[type] = list;
  return list;
}

DeviceCore::ProfileEntry DeviceCore::sourceFor(const std::shared_ptr<ob::StreamProfile> &profile) {
  std::lock_guard<std::mutex> lock(profile_mutex);
  auto it = profile_sources.find(profile.get());
  if (it == profile_sources.end()) {
    // Profiles of a companion device live in the companion's registry.
    if (companion) {
      return companion->sourceFor(profile);
    }
    throwError("Stream profile was not created by this device");
  }
  return it->second;
}

