void DeviceCore::startStreams(const std::vector<std::shared_ptr<ob::StreamProfile>> &profiles,
                              const std::map<int, RawFrameCallback> &callbacks) {
  std::lock_guard<std::mutex> lock(runner_mutex);
  if (!runners.empty()) {
    throwError("DeviceCore::startStreams: streams are already running");
  }
  try {
    for (const auto &profile : profiles) {
      if (!profile) {
        continue;
      }
      ProfileEntry entry = sourceFor(profile);
      DeviceCorePtr owner = entry.owner ? entry.owner : shared_from_this();
      const ProfileSource &source = entry.source;
      int iface = source.streaming_interface;

      if (owner.get() == this && klass == ProductClass::kGeminiOpenNI) {
        // Vendor-bulk depth stream (interface index -1).
        if (runners.count(iface)) {
          continue;
        }
        auto cb_it = callbacks.find(iface);
        if (cb_it == callbacks.end()) {
          throwError("No frame callback registered for the vendor stream");
        }
        auto video = profile->as<ob::VideoStreamProfile>();
        auto runner = createVendorNiRunner(shared_from_this(), OB_SENSOR_DEPTH, source,
                                           video->width(), video->height());
        runner->start(cb_it->second);
        runners[iface] = runner;
        continue;
      }

      if (owner.get() != this) {
        // Companion-owned (UVC) profile: run it on the companion core.
        std::map<int, RawFrameCallback> one{{iface, callbacks.at(iface)}};
        owner->startStreams({profile}, one);
        runners[iface] = nullptr;  // marker: owned by the companion
        continue;
      }

      if (iface < 0) {
        throwError("Stream profile has no source interface");
      }
      if (runners.count(iface)) {
        // Two enabled profiles sharing one VS interface cannot stream at once.
        OBSDK_WARN("Two stream profiles share streaming interface " << iface
                                                                   << "; the first one wins");
        continue;
      }
      auto cb_it = callbacks.find(iface);
      if (cb_it == callbacks.end()) {
        throwError("No frame callback registered for streaming interface " +
                   std::to_string(iface));
      }
      auto runner = createUvcRunner(shared_from_this(), iface, source);
      runner->start(cb_it->second);
      runners[iface] = runner;
    }
    // Drop companion markers before the empty check (they hold no runner here).
    for (auto it = runners.begin(); it != runners.end();) {
      it = (it->second == nullptr) ? runners.erase(it) : std::next(it);
    }
    if (runners.empty() && !callbacks.empty()) {
      // All enabled profiles may be companion-owned; that is fine as long as
      // the companion actually started something (startStreams would have
      // thrown otherwise).
      return;
    }
    if (runners.empty()) {
      throwError("DeviceCore::startStreams: no stream could be started");
    }
  } catch (...) {
    // Roll back partially started streams so a retry can start cleanly.
    for (auto &entry : runners) {
      if (entry.second) {
        entry.second->stop();
      }
    }
    runners.clear();
    if (companion) {
      companion->stopStreams();
    }
    throw;
  }
}

void DeviceCore::stopStreams() {
  std::map<int, std::shared_ptr<StreamRunner>> to_stop;
  {
    std::lock_guard<std::mutex> lock(runner_mutex);
    to_stop.swap(runners);
  }
  for (auto &entry : to_stop) {
    if (entry.second) {
      entry.second->stop();
    }
  }
  if (companion) {
    companion->stopStreams();
  }
}

